/**
 * Bible Book 30: ஆமோஸ் (Amos)
 */
if (typeof window.registerBibleBook === 'function') {
  window.registerBibleBook(30, {"id": 30, "testament": "OT", "code": "AMO", "name_en": "Amos", "name_ta": "ஆமோஸ்", "category": "Minor Prophets", "category_ta": "சிறிய தீர்க்கதரிசிகள்", "total_chapters": 9, "chapters": {"1": {"chapter": 1, "duration": 211.86, "audio_url": "audio_ot/OT30_01.mp3", "total_verses": 15, "verses": [{"verse": 1, "start": 4.8, "end": 24.45, "ta": "தெக்கோவா ஊர் மேய்ப்பருக்குள் இருந்த ஆமோஸ், யூதாவின் ராஜாவாகிய உசியாவின் நாட்களிலும், இஸ்ரவேலின் ராஜாவாகிய யோவாசுடைய குமாரனாகிய எரொபெயாமின் நாட்களிலும், பூமி அதிர்ச்சி உண்டாக இரண்டு வருஷத்துக்கு முன்னே, இஸ்ரவேலைக்குறித்துத் தரிசனங்கண்டு சொன்ன வார்த்தைகள்.", "en": "The words of Amos, who was among the herdmen of Tekoa, which he saw concerning Israel in the days of Uzziah king of Judah, and in the days of Jeroboam the son of Joash king of Israel, two years before the earthquake."}, {"verse": 2, "start": 24.45, "end": 37.31, "ta": "கர்த்தர் சீயோனிலிருந்து கெர்ச்சித்து, எருசலேமிலிருந்து சத்தமிடுவார்; அதினால் மேய்ப்பரின் தாபரங்கள் துக்கங்கொண்டாடும்; கர்மேலின் கொடுமுடியும் காய்ந்துபோகும்.", "en": "And he said, The LORD will roar from Zion, and utter his voice from Jerusalem; and the habitations of the shepherds shall mourn, and the top of Carmel shall wither."}, {"verse": 3, "start": 37.31, "end": 53.1, "ta": "கர்த்தர் சொல்லுகிறது என்னவென்றால்: தமஸ்குவினுடைய மூன்று பாதகங்களினிமித்தமும், நாலு பாதகங்களினிமித்தமும், நான் அதின் ஆக்கினையைத் திருப்பமாட்டேன்; அவர்கள் கீலேயாத்தை இருப்புக் கருவிகளினால் அடித்தார்களே.", "en": "Thus saith the LORD ; For three transgressions of Damascus, and for four, I will not turn away the punishment thereof; because they have threshed Gilead with threshing instruments of iron:"}, {"verse": 4, "start": 53.1, "end": 59.6, "ta": "ஆசகேலின் வீட்டிலே தீக்கொளுத்துவேன்; அது பெனாதாத்தின் அரமனைகளைப் பட்சிக்கும்.", "en": "But I will send a fire into the house of Hazael, which shall devour the palaces of Ben-hadad."}, {"verse": 5, "start": 59.6, "end": 78.18, "ta": "நான் தமஸ்குவின் தாழப்பாளை உடைத்து, குடிகளை ஆவேன் என்னும் பள்ளத்தாக்கிலும், செங்கோல் செலுத்துகிறவனைப் பெத்எதேனிலும் இராதபடிக்குச் சங்காரம்பண்ணுவேன்; அப்பொழுது சீரியாவின் ஜனங்கள் கீருக்குச் சிறைப்பட்டுப்போவார்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "I will break also the bar of Damascus, and cut off the inhabitant from the plain of Aven, and him that holdeth the sceptre from the house of Eden: and the people of Syria shall go into captivity unto Kir, saith the LORD ."}, {"verse": 6, "start": 78.18, "end": 96.04, "ta": "கர்த்தர் சொல்லுகிறது என்னவென்றால்: காத்சாவினுடைய மூன்று பாதங்களினிமித்தமும், நாலு பாதகங்களினிமித்தமும், நான் அதின் ஆக்கினையைத் திருப்பமாட்டேன்; அவர்கள் சிறைப்பட்டவர்களை ஏதோமியரிடத்தில் ஒப்புவிக்கும்படி முழுதும் சிறையாக்கினார்களே.", "en": "Thus saith the LORD ; For three transgressions of Gaza, and for four, I will not turn away the punishment thereof; because they carried away captive the whole captivity, to deliver them up to Edom:"}, {"verse": 7, "start": 96.04, "end": 102.54, "ta": "காத்சாவின் மதிலுக்குள் தீக்கொளுத்துவேன்; அது அதினுடைய அரமனைகளைப் பட்சிக்கும.", "en": "But I will send a fire on the wall of Gaza, which shall devour the palaces thereof:"}, {"verse": 8, "start": 102.54, "end": 118.69, "ta": "நான் குடிகளை அஸ்தோத்திலும், செங்கோல் செலுத்துகிறவனை அஸ்கலோனிலும் இராதபடிக்குச் சங்காரம்பண்ணி, பெலிஸ்தரில் மீதியானவர்கள் அழியும்படிக்கு என் கையை எனக்கு விரோதமாகத திருப்புவேனென்று கர்த்தராகிய ஆண்டவர் சொல்லுகிறார்.", "en": "And I will cut off the inhabitant from Ashdod, and him that holdeth the sceptre from Ashkelon, and I will turn mine hand against Ekron: and the remnant of the Philistines shall perish, saith the Lord GOD ."}, {"verse": 9, "start": 118.69, "end": 135.7, "ta": "மேலும்: தீருவினுடைய மூன்று பாதகங்களினிமித்தமும், நாலு பாதகங்களினிமித்தமும், நான் அதின் ஆக்கினையைத் திருப்பமாட்டேன்; அவர்கள் சகோதரன் உடன்படிக்கையை நினையாமல், சிறைப்பட்டவர்களை முழுதும் ஏதோமியர் கையில் ஒப்பித்தார்களே.", "en": "Thus saith the LORD ; For three transgressions of Tyrus, and for four, I will not turn away the punishment thereof; because they delivered up the whole captivity to Edom, and remembered not the brotherly covenant:"}, {"verse": 10, "start": 135.7, "end": 143.91, "ta": "தீருவின் மதிலுக்குள் தீக்கொளுத்துவேன்; அது அதின் அரமனைகளைப் பட்சிக்கும் என்று கர்த்தர் சொல்லுகிறார்.", "en": "But I will send a fire on the wall of Tyrus, which shall devour the palaces thereof."}, {"verse": 11, "start": 143.91, "end": 165.78, "ta": "மேலும்: ஏதோமுடைய மூன்று பாதகங்களினிமித்தமும், நாலு பாதகங்களினிமித்தமும், நான் அவன் ஆக்கினையைத் திருப்பமாட்டேன்; அவன் தன் சகோதரனைப் பட்டயத்தோடே தொடர்ந்து, தன் மனதை இரக்கமற்றதாக்கி, தன் கோபத்தினாலே என்றைக்கும் அவனைப் பீறிப்போட்டு, தன் மூர்க்கத்தை நித்தியகாலமாக வைத்திருக்கிறானே.", "en": "Thus saith the LORD ; For three transgressions of Edom, and for four, I will not turn away the punishment thereof; because he did pursue his brother with the sword, and did cast off all pity, and his anger did tear perpetually, and he kept his wrath for ever:"}, {"verse": 12, "start": 165.78, "end": 173.42, "ta": "தேமானிலே: தீக்கொளுத்துவேன்; அது போஸ்றாவின் அரமனைகளைப் பட்சிக்கும் என் கர்த்தர் சொல்லுகிறார்.", "en": "But I will send a fire upon Teman, which shall devour the palaces of Bozrah."}, {"verse": 13, "start": 173.42, "end": 192.64, "ta": "கர்த்தர் சொல்லுகிறது என்னவன்றால்: அம்மோன் புத்திரரின் மூன்று பாதகங்களினிமித்தமும் நாலு பாதகங்களினிமித்தமும் நான் அவர்கள் ஆக்கினையைத் திருப்பமாட்டேன்; அவர்கள் தங்கள் எல்லைகளை விஸ்தாரமாக்கும்படிக்குக் கீலேயாத் தேசத்தின் கர்ப்பஸ்திரீகளைக் கீறிப்போட்டார்களே.", "en": "Thus saith the LORD ; For three transgressions of the children of Ammon, and for four, I will not turn away the punishment thereof; because they have ripped up the women with child of Gilead, that they might enlarge their border:"}, {"verse": 14, "start": 192.64, "end": 202.93, "ta": "ரப்பாவின் மதிலுக்குள் தீக்கொளுத்துவேன்; அது யுத்தநாளின் முழக்கமாகவும், பெருங்காற்றின் புசலாகவும் அதின் அரமனைகளைப் பட்சிக்கும்.", "en": "But I will kindle a fire in the wall of Rabbah, and it shall devour the palaces thereof, with shouting in the day of battle, with a tempest in the day of the whirlwind:"}, {"verse": 15, "start": 202.93, "end": 210.36, "ta": "அவர்களுடைய ராஜாவும், அவனுடைய அதிபதிகளும் சிறைப்பட்டுப்போவார்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And their king shall go into captivity, he and his princes together, saith the LORD ."}]}, "2": {"chapter": 2, "duration": 204.17, "audio_url": "audio_ot/OT30_02.mp3", "total_verses": 16, "verses": [{"verse": 1, "start": 3.8, "end": 19.35, "ta": "கர்த்தர் சொல்லுகிறது என்னவென்றால்: மோவாபின் மூன்று பாதகங்களினிமித்தமும், நாலு பாதகங்களினிமித்தமும், நான் அவன் ஆக்கினையைத் திருப்பமாட்டேன்; அவன் ஏதோமுடைய ராஜாவின் எலும்புகளை நீறாகச் சுட்டுப்போட்டானே.", "en": "Thus saith the LORD ; For three transgressions of Moab, and for four, I will not turn away the punishment thereof; because he burned the bones of the king of Edom into lime:"}, {"verse": 2, "start": 19.35, "end": 30.99, "ta": "மோவாப்தேசத்தில் தீக்கொளுத்துவேன்; அது கீரியாத்தின் அரமனைகளைப் பட்சிக்கும்; மோவாபியர் அமளியோடும் ஆர்ப்பரிப்போடும் எக்காள சத்தத்தோடும் சாவார்கள்.", "en": "But I will send a fire upon Moab, and it shall devour the palaces of Kerioth: and Moab shall die with tumult, with shouting, and with the sound of the trumpet:"}, {"verse": 3, "start": 30.99, "end": 41.93, "ta": "நியாயாதிபதியை அவர்கள் நடுவில் இராதபடிக்கு நான் சங்காரம்பண்ணி, அவனோடே அவர்களுடைய பிரபுக்களையெல்லாம் கொன்றுபோடுவேன் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And I will cut off the judge from the midst thereof, and will slay all the princes thereof with him, saith the LORD ."}, {"verse": 4, "start": 41.93, "end": 60.53, "ta": "மேலும்: யூதாவின் மூன்று பாதகங்களினிமித்தமும் நாலு பாதகங்களினிமித்தமும் நான் அவர்கள் ஆக்கினையைத் திருப்பமாட்டேன்; அவர்கள் கர்த்தருடைய வேதத்தை வெறுத்து, அவருடைய கட்டளைகளைக் கைக்கொள்ளாமல், தங்கள் பிதாக்கள் பின்பற்றின பொய்களினால் மோசம்போனார்களே.", "en": "Thus saith the LORD ; For three transgressions of Judah, and for four, I will not turn away the punishment thereof; because they have despised the law of the LORD , and have not kept his commandments, and their lies caused them to err, after the which their fathers have walked:"}, {"verse": 5, "start": 60.53, "end": 68.55, "ta": "யூதாவிலே நான் தீக்கொளுத்துவேன்; அது எருசலேமின் அரமனைகளைப் பட்சிக்கும் என்று கர்த்தர் சொல்லுகிறார்.", "en": "But I will send a fire upon Judah, and it shall devour the palaces of Jerusalem."}, {"verse": 6, "start": 68.55, "end": 84.6, "ta": "மேலும்: இஸ்ரவேலின் மூன்று பாதகங்களினிமித்தமும், நாலு பாதகங்களினிமித்தமும், நான் அவர்களுடைய ஆக்கினையைத் திருப்பமாட்டேன், அவர்கள் நீதிமானைப் பணத்துக்கும், எளியவனை ஒரு ஜோடு பாதரட்சைக்கும் விற்றுப்போட்டார்களே.", "en": "Thus saith the LORD ; For three transgressions of Israel, and for four, I will not turn away the punishment thereof; because they sold the righteous for silver, and the poor for a pair of shoes;"}, {"verse": 7, "start": 84.6, "end": 99.86, "ta": "அவர்கள் தரித்திரருடைய தலையின்மேல் மண்ணைவாரி இறைத்து, சிறுமையானவர்களின் வழியைப் புரட்டுகிறார்கள்; என் பரிசுத்த நாமத்தைக் குலைச்சலாக்கும்படிக்கு மகனும் தகப்பனும் ஒரு பெண்ணிடத்தில் பிரவேசிக்கிறார்கள்.", "en": "That pant after the dust of the earth on the head of the poor, and turn aside the way of the meek: and a man and his father will go in unto the same maid, to profane my holy name:"}, {"verse": 8, "start": 99.86, "end": 114.7, "ta": "அவர்கள் சகல பீடங்களருகிலும் அடைமானமாய் வாங்கின வஸ்திரங்களின்மேல் படுத்துக்கொண்டு, தெண்டம் பிடிக்கப்பட்டவர்களுடைய மதுபானத்தைத் தங்கள் தேவர்களின் கோவிலிலே குடிக்கிறார்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And they lay themselves down upon clothes laid to pledge by every altar, and they drink the wine of the condemned in the house of their god."}, {"verse": 9, "start": 114.7, "end": 129.19, "ta": "நானோ: கேதுருமரங்களைப்போல் உயரமும், கர்வாலி மரங்களைப்போல் வைரமுமாயிருந்த எமோரியனை அவர்களுக்கு முன்பாக அழித்தேன்; உயர இருந்த அவனுடைய கனியையும், தாழ இருந்த அவனுடைய வேர்களையும் அழித்துப்போட்டு,", "en": "Yet destroyed I the Amorite before them, whose height was like the height of the cedars, and he was strong as the oaks; yet I destroyed his fruit from above, and his roots from beneath."}, {"verse": 10, "start": 129.19, "end": 139.98, "ta": "நீங்கள் எமோரியனுடைய தேசத்தைக் கட்டிக்கொள்ளும்படிக்கு உங்களை நான் எகிப்துதேசத்திலிருந்து வரப்பண்ணி, உங்களை நாற்பது வருஷமாக வனாந்தரத்திலே வழிநடத்தி,", "en": "Also I brought you up from the land of Egypt, and led you forty years through the wilderness, to possess the land of the Amorite."}, {"verse": 11, "start": 139.98, "end": 153.54, "ta": "உங்கள் குமாரரில் சிலரைத் தீர்க்கதரிசிகளாகவும் உங்கள் வாலிபரில் சிலரை நசரேயராகவும் எழும்பப்பண்ணினேன்; இஸ்ரவேல் புத்திரரே, இப்படி நான் செய்யவில்லையா என்று கர்த்தர் கேட்கிறார்.", "en": "And I raised up of your sons for prophets, and of your young men for Nazarites. Is it not even thus, O ye children of Israel? saith the LORD ."}, {"verse": 12, "start": 153.54, "end": 163.98, "ta": "நீங்களோ நசரேயருக்குத் திராட்சரசம் குடிக்கக் கொடுத்து, தீர்க்கதரிசிகளை நோக்கி: நீங்கள் தீர்க்கதரிசனஞ்சொல்லவேண்டாம் என்று கற்பித்தீர்கள்.", "en": "But ye gave the Nazarites wine to drink; and commanded the prophets, saying, Prophesy not."}, {"verse": 13, "start": 163.98, "end": 173.77, "ta": "இதோ, கோதுமைக்கட்டுகள் நிறைபாரமாக ஏற்றப்பட்ட வண்டியில் இருத்துகிறதுபோல, நான் உங்களை நீங்கள் இருக்கிற ஸ்தலத்தில் இருத்துவேன்.", "en": "Behold, I am pressed under you, as a cart is pressed that is full of sheaves."}, {"verse": 14, "start": 173.77, "end": 184.42, "ta": "அப்பொழுது வேகமானவன் ஓடியும் புகலிடமில்லை; பலவான் தன் பலத்தினால் பலப்படுவதுமில்லை; பராக்கிரமசாலி தன் பிராணனைத் தப்புவிப்பதுமில்லை.", "en": "Therefore the flight shall perish from the swift, and the strong shall not strengthen his force, neither shall the mighty deliver himself:"}, {"verse": 15, "start": 184.42, "end": 195.57, "ta": "வில்லைப் பிடிக்கிறவன் நிற்பதுமில்லை; வேகமானன் தன் கால்களால் தப்பிப்போவதுமில்லை; குதிரையின் மேல் ஏறுகிறவன் தன் பிராணனை இரட்சிப்பதுமில்லை.", "en": "Neither shall he stand that handleth the bow; and he that is swift of foot shall not deliver himself: neither shall he that rideth the horse deliver himself."}, {"verse": 16, "start": 195.57, "end": 202.67, "ta": "பலசாலிகளுக்குள்ளே தைரியவான் அந்நாளிலே நிர்வாணியாய் ஓடிப்போவான் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And he that is courageous among the mighty shall flee away naked in that day, saith the LORD ."}]}, "3": {"chapter": 3, "duration": 171.88, "audio_url": "audio_ot/OT30_03.mp3", "total_verses": 15, "verses": [{"verse": 1, "start": 3.8, "end": 14.52, "ta": "இஸ்ரவேல் புத்திரரே, கர்த்தராகிய நான் எகிப்துதேசத்திலிருந்து வரப்பண்ணின முழுக்குடும்பமாகிய உங்களுக்கு விரோதமாய்ச் சொல்லிய இந்த வசனத்தைக் கேளுங்கள்.", "en": "Hear this word that the LORD hath spoken against you, O children of Israel, against the whole family which I brought up from the land of Egypt, saying,"}, {"verse": 2, "start": 14.52, "end": 24.89, "ta": "பூமியின் எல்லா வம்சங்களுக்குள்ளும் உங்களை மாத்திரம் அறிந்துகொண்டேன்; ஆகையால் உங்களுடைய எல்லா அக்கிரமங்களினிமித்தமும் உங்களைத் தண்டிப்பேன்.", "en": "You only have I known of all the families of the earth: therefore I will punish you for all your iniquities."}, {"verse": 3, "start": 24.89, "end": 29.64, "ta": "இரண்டுபேர் ஒருமனப்பட்டிருந்தாலொழிய ஒருமித்து நடந்துபோவார்களோ?", "en": "Can two walk together, except they be agreed?"}, {"verse": 4, "start": 29.64, "end": 39.41, "ta": "தனக்கு இரை அகப்படாமலிருக்கக் காட்டிலே சிங்கம் கெர்ச்சிக்குமோ? இரை அகப்படாமலிருக்கும் பாலசிங்கம் தன் கெபியிலிருந்து சத்தமிடுமோ?", "en": "Will a lion roar in the forest, when he hath no prey? will a young lion cry out of his den, if he have taken nothing?"}, {"verse": 5, "start": 39.41, "end": 50.19, "ta": "குருவிக்குத் தரையிலே சுருக்குப்போடப்படாதிருந்தால், அது கண்ணியில் அகப்படுமோ? ஒன்றும் படாதிருக்கையில், கண்ணி தரையிலிருந்து எடுக்கப்படுமோ?", "en": "Can a bird fall in a snare upon the earth, where no gin is for him? shall one take up a snare from the earth, and have taken nothing at all?"}, {"verse": 6, "start": 50.19, "end": 58.33, "ta": "ஊரில் எக்காளம் ஊதினால் ஜனங்கள் கலங்காதிருப்பார்களோ? கர்த்தருடைய செயல் இல்லாமல் ஊரில் தீங்கு உண்டாகுமோ?", "en": "Shall a trumpet be blown in the city, and the people not be afraid? shall there be evil in a city, and the LORD hath not done it ? …: or, shall not the LORD do somewhat?"}, {"verse": 7, "start": 58.33, "end": 67.49, "ta": "கர்த்தராகிய ஆண்டவர் தீர்க்கதரிசிகளாகிய தம்முடைய ஊழியக்காரருக்குத் தமது இரகசியத்தை வெளிப்படுத்தாமல் ஒரு காரியத்தையும் செய்யார்.", "en": "Surely the Lord GOD will do nothing, but he revealeth his secret unto his servants the prophets."}, {"verse": 8, "start": 67.49, "end": 77.12, "ta": "சிங்கம் கெர்ச்சிக்கிறது, யார் பயப்படாதிருப்பான்? கர்த்தராகிய ஆண்டவர் பேசுகிறார், யார் தீர்க்கதரிசனம் சொல்லாதிருப்பான்?", "en": "The lion hath roared, who will not fear? the Lord GOD hath spoken, who can but prophesy?"}, {"verse": 9, "start": 77.12, "end": 92.38, "ta": "நாங்கள் சமாரியாவின் பர்வதங்களில வந்து கூடி, அதின் நடுவில் நடக்கிற பெரிய கலகங்களையும் அதற்குள் செய்யப்படுகிற இடுக்கண்களையும் பாருங்கள் என்று அஸ்தோத்தின் அரமனைகள்மேலும், எகிப்துதேசத்தின் அரமனைகள்மேலும் கூறுங்கள்.", "en": "Publish in the palaces at Ashdod, and in the palaces in the land of Egypt, and say, Assemble yourselves upon the mountains of Samaria, and behold the great tumults in the midst thereof, and the oppressed in the midst thereof."}, {"verse": 10, "start": 92.38, "end": 102.42, "ta": "அவர்கள் செம்மையானதைச் செய்ய அறியாமல், தங்கள் அரமனைகளில் கொடுமையையும் கொள்ளையையும் குவித்துக்கொள்ளுகிறார்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "For they know not to do right, saith the LORD , who store up violence and robbery in their palaces."}, {"verse": 11, "start": 102.42, "end": 115.51, "ta": "ஆகையால் சத்துரு வந்து, தேசத்தைச் சூழ்ந்துகொண்டு உன்பெலத்தை உன்னிலிருந்து அற்றுப்போகப்பண்ணுவான்; அப்பொழுது உன் அரமனைகள் கொள்ளையிடப்படும் என்று கர்த்தராகிய ஆண்டவர் சொல்லுகிறார்.", "en": "Therefore thus saith the Lord GOD ; An adversary there shall be even round about the land; and he shall bring down thy strength from thee, and thy palaces shall be spoiled."}, {"verse": 12, "start": 115.51, "end": 135.52, "ta": "மேலும்: ஒரு மேய்ப்பன் இரண்டு கால்களையாவது ஒரு காதின் துண்டையாவது சிங்கத்தின் வாயிலிருந்து பிடுங்கித் தப்புவிக்குமாப்போல, சமாரியாவில் குடியிருக்கிற இஸ்ரவேல் புத்திரர் ஒரு படுக்கையின் மூலையிலிருந்தும், ஒரு மஞ்சத்தின்மேலிருந்தும் தப்புவிக்கப்படுவார்களென்று, கர்த்தர் சொல்லுகிறார்.", "en": "Thus saith the LORD ; As the shepherd taketh out of the mouth of the lion two legs, or a piece of an ear; so shall the children of Israel be taken out that dwell in Samaria in the corner of a bed, and in Damascus in a couch."}, {"verse": 13, "start": 135.52, "end": 145.89, "ta": "ஆகையால் நீங்கள் கேட்டு யாக்கோபு வம்சத்தாருக்குள்ளே சாட்சியாக அறிவிக்கவேண்டியது: சேனைகளின் தேவனாயிருக்கிற கர்த்தராகிய ஆண்டவர் சொல்லுகிறது என்னவென்றால்,", "en": "Hear ye, and testify in the house of Jacob, saith the Lord GOD , the God of hosts,"}, {"verse": 14, "start": 145.89, "end": 157.15, "ta": "நான் இஸ்ரவேலுடைய பாதகங்களினிமித்தம் அவனை விசாரிக்கும்நாளிலே நான் பெத்தேலின் பலிபீடங்களை விசாரிப்பேன்; பலிபீடத்தின் கொம்புகள் வெட்டுண்டு தரையிலே விழும்.", "en": "That in the day that I shall visit the transgressions of Israel upon him I will also visit the altars of Beth-el: and the horns of the altar shall be cut off, and fall to the ground."}, {"verse": 15, "start": 157.15, "end": 170.38, "ta": "மாரிகாலத்Ġρ வீட்டையும் கோடைகாலத்து வீட்டையும் அழοப்பேன்; அப்பொழுது யானைத்தந்தத்தால் செய்யப்பட்ட வீடுகள் அழியும்; பெரிய வீடுகளுக்கும் முடிவு வரும் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And I will smite the winter house with the summer house; and the houses of ivory shall perish, and the great houses shall have an end, saith the LORD ."}]}, "4": {"chapter": 4, "duration": 204.51, "audio_url": "audio_ot/OT30_04.mp3", "total_verses": 13, "verses": [{"verse": 1, "start": 3.8, "end": 19.59, "ta": "சமாரியாவின் மலைகளிலுள்ள பாசானின் மாடுகளே, நீங்கள் இந்த வார்த்தைகளைக் கேளுங்கள்; தரித்திரரை ஒடுக்கி, எளியவர்களை நொறுக்கி, அவர்களுடைய எஜமான்களை நோக்கி: நாங்கள் குடிக்கும்படிக் கொண்டுவாருங்கள் என்று சொல்லுகிறீர்கள்.", "en": "Hear this word, ye kine of Bashan, that are in the mountain of Samaria, which oppress the poor, which crush the needy, which say to their masters, Bring, and let us drink."}, {"verse": 2, "start": 19.59, "end": 32.97, "ta": "இதோ, கர்த்தராகிய ஆண்டவர் உங்களைத் துறடுகளாலும், உங்கள் பின்சந்ததியை மீன்பிடிக்கிற தூண்டில்களாலும் இழுத்துக்கொண்டுபோகும் நாட்கள் வருமென்று அவர் தம்முடைய பரிசுத்தத்தைக்கொண்டு ஆணையிட்டார்.", "en": "The Lord GOD hath sworn by his holiness, that, lo, the days shall come upon you, that he will take you away with hooks, and your posterity with fishhooks."}, {"verse": 3, "start": 32.97, "end": 44.74, "ta": "அப்பொழுது நீங்கள் ஒவ்வொருவனும் அரமனைக்குச் சுமந்துகொண்டுபோவதை எறிந்துவிட்டு, தனக்கு எதிரான திறப்புகளின் வழியாய்ப் புறப்பட்டுப்போவீர்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And ye shall go out at the breaches, every cow at that which is before her; and ye shall cast them into the palace, saith the LORD ."}, {"verse": 4, "start": 44.74, "end": 56.71, "ta": "பெத்தேலுக்குப் போய்த் துரோகம் பண்ணுங்கள், கில்காலுக்குப்போய்த் துரோகத்தைப் பெருகப்பண்ணி, காலைதோறும் உங்கள் பலிகளையும் மூன்றாம் வருஷத்திலே உங்கள் தசமபாகங்களையும் செலுத்தி,", "en": "Come to Beth-el, and transgress; at Gilgal multiply transgression; and bring your sacrifices every morning, and your tithes after three years:"}, {"verse": 5, "start": 56.71, "end": 70.56, "ta": "புளித்தமாவுள்ள ஸ்தோத்திரபலியோடே தூபங்காட்டி, உற்சாக பலிகளைக் கூறித் தெரியப்படுத்துங்கள்; இஸ்ரவேல் புத்திரரே, இப்படிச் செய்வதே உங்களுக்குப் பிரியம் என்று கர்த்தராகிய ஆண்டவர் சொல்லுகிறார்.", "en": "And offer a sacrifice of thanksgiving with leaven, and proclaim and publish the free offerings: for this liketh you, O ye children of Israel, saith the Lord GOD ."}, {"verse": 6, "start": 70.56, "end": 85.81, "ta": "ஆகையால் நான் உங்கள் பட்டணங்களில் எல்லாம் உங்கள் பல்லுகளுக்கு ஓய்வையும், உங்கள் ஸ்தலங்களில் எல்லாம் அப்பக்குறைவையும் கட்டளையிட்டேன்; ஆகிலும் நீங்களே என்னிடத்தில் திரும்பாமற்போனீர்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And I also have given you cleanness of teeth in all your cities, and want of bread in all your places: yet have ye not returned unto me, saith the LORD ."}, {"verse": 7, "start": 85.81, "end": 103.34, "ta": "இதுவுமல்லாமல் அறுப்புக்காலம் வர இன்னும் மூன்றுமாதம் இருக்கும்போதே மழையை நான் தடுத்தேன், ஒரு பட்டணத்தின்மேல் மழைபெய்யவும் ஒரு பட்டணத்தின்மேல் மழை பெய்யாமலிருக்கவும் பண்ணினேன்; ஒரு வயலின்மேல் மழைபெய்தது, மழைபெய்யாத மற்ற வயல் காய்ந்து போயிற்று.", "en": "And also I have withholden the rain from you, when there were yet three months to the harvest: and I caused it to rain upon one city, and caused it not to rain upon another city: one piece was rained upon, and the piece whereupon it rained not withered."}, {"verse": 8, "start": 103.34, "end": 116.72, "ta": "இரண்டு மூன்று பட்டணங்களின் மனுஷர் தண்ண ΰ் குடிக்க பட்டணத்துக்குப் போய் அலைந்தும் தாகந்தீத்துக்கொள்ளவில்லை; ஆகிலும் நீங்கள் என்னிடத்தில் திரும்பாமற்போனீர்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "So two or three cities wandered unto one city, to drink water; but they were not satisfied: yet have ye not returned unto me, saith the LORD ."}, {"verse": 9, "start": 116.72, "end": 134.38, "ta": "கருக்காயினாலும் விஷப்பனியினாலும் உங்களை தண்டித்தேன்; உங்கள் சோலைகளிலும் திராட்சத்தோட்டங்களிலும் அத்திமரங்களிலும் ஒலிவமரங்களிலும் மிகுதியானதைப் பச்சைப்புழு அரித்துப்போட்டது; ஆகிலும் என்னிடத்தில் திரும்பாமற்போனார்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "I have smitten you with blasting and mildew: when your gardens and your vineyards and your fig trees and your olive trees increased, the palmerworm devoured them: yet have ye not returned unto me, saith the LORD ."}, {"verse": 10, "start": 134.38, "end": 155.45, "ta": "எகிப்தில் உண்டானதற்கு ஒத்த கொள்ளைநோயை உங்களுக்குள் அனுப்பினேன்; உங்கள் வாலிபரைப் பட்டயத்தாலே கொன்றேன்; உங்கள் குதிரைகளை அழித்துப்போட்டேன்; உங்கள் பாளயங்களின் நாற்றத்தை உங்கள் நாசிகளிலும் ஏற்றப்பண்ணினேன்; ஆகிலும் நீங்கள் என்னிடத்தில் திரும்பாமற்போனீர்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "I have sent among you the pestilence after the manner of Egypt: your young men have I slain with the sword, and have taken away your horses; and I have made the stink of your camps to come up unto your nostrils: yet have ye not returned unto me, saith the LORD ."}, {"verse": 11, "start": 155.45, "end": 172.17, "ta": "சோதோமையும் கொமோராவையும் தேவன் கவிழ்த்துப்போட்டதுபோல, உங்களைக் கவிழ்த்துப்போட்டேன்; நீங்கள் அக்கினியினின்று பறிக்கப்பட்ட கொள்ளியைப்போல இருந்தீர்கள்; ஆனாலும் நீங்கள் என்னிடத்தில் திரும்பாமற்போனீர்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "I have overthrown some of you, as God overthrew Sodom and Gomorrah, and ye were as a firebrand plucked out of the burning: yet have ye not returned unto me, saith the LORD ."}, {"verse": 12, "start": 172.17, "end": 183.14, "ta": "ஆகையால் இஸ்ரவேலே, இந்தப்பிரகாரமாக உனக்குச் செய்வேன்; இஸ்ரவேலே, நான் இப்படி உனக்குச்செய்யப்போகிறபடியினால் உன் தேவனைச் சந்திக்கும்படி ஆயத்தப்படு.", "en": "Therefore thus will I do unto thee, O Israel: and because I will do this unto thee, prepare to meet thy God, O Israel."}, {"verse": 13, "start": 183.14, "end": 203.01, "ta": "அவர் பர்வதங்களை உருவாக்கினவரும் காற்றைச் சிருஷ்டித்தவரும், மனுஷனுடைய நினைவுகள் இன்னதென்று அவனுக்கு வெளிப்படுத்துகிறவரும், விடியற்காலத்தை அந்தகாரமாக்குகிறவரும், பூமியினுடைய உயர்ந்த ஸ்தானங்களின்மேல் உலாவுகிறவருமாயிருக்கிறார்; சேனைகளின் தேவனாகிய கர்த்தர் என்பது அவருடைய நாமம்.", "en": "For, lo, he that formeth the mountains, and createth the wind, and declareth unto man what is his thought, that maketh the morning darkness, and treadeth upon the high places of the earth, The LORD , The God of hosts, is his name."}]}, "5": {"chapter": 5, "duration": 298.24, "audio_url": "audio_ot/OT30_05.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 10.83, "ta": "இஸ்ரவேல் வம்சத்தாரே, உங்களைக்குறித்து நான் புலம்பிச் சொல்லும் இந்த வசனத்தைக் கேளுங்கள்.", "en": "Hear ye this word which I take up against you, even a lamentation, O house of Israel."}, {"verse": 2, "start": 10.83, "end": 21.69, "ta": "இஸ்ரவேல் என்னும் கன்னிகை விழுந்தாள், அவள் இனி ஒருபோதும் எழுந்திருக்கமாட்டாள்; தன் தேசத்தில் விழுந்துகிடக்கிறாள், அவளை எடுப்பாரில்லை.", "en": "The virgin of Israel is fallen; she shall no more rise: she is forsaken upon her land; there is none to raise her up."}, {"verse": 3, "start": 21.69, "end": 33.55, "ta": "நகரத்திலிருந்து புறப்பட்ட ஆயிரம்பேரில் நூறுபேரும், நூறுபேரில் பத்துப்பேரும் இஸ்ரவேல் வம்சத்தாருக்கு மீந்திருப்பார்கள் என்று கர்த்தராகிய தேவன் சொல்லுகிறார்.", "en": "For thus saith the Lord GOD ; The city that went out by a thousand shall leave an hundred, and that which went forth by an hundred shall leave ten, to the house of Israel."}, {"verse": 4, "start": 33.55, "end": 41.71, "ta": "கர்த்தர் இஸ்ரவேல் வம்சத்தாருக்குச் சொல்லுகிறது என்னவென்றால் என்னைத் தேடுங்கள், அப்பொழுது பிழைப்பீர்கள்.", "en": "For thus saith the LORD unto the house of Israel, Seek ye me, and ye shall live:"}, {"verse": 5, "start": 41.71, "end": 54.07, "ta": "பெத்தேலைத் தேடாதேயுங்கள், கில்காலிலும் சேராதேயுங்கள், பெயெர்செபாவுக்கும் போகாதேயுங்கள்; கில்கால் கிறையிருப்பாகவும், பெத்தேல் பாழான ஸ்தலமாகவும் போகும்.", "en": "But seek not Beth-el, nor enter into Gilgal, and pass not to Beer-sheba: for Gilgal shall surely go into captivity, and Beth-el shall come to nought."}, {"verse": 6, "start": 54.07, "end": 66.63, "ta": "கர்த்தரைத் தேடுங்கள், அப்பொழுது பிழைப்பீர்கள்; இல்லாவிட்டால் பெத்தேலில் இருக்கிற ஒருவராலும் அறிவிக்கப்படாத அக்கினி யோசேப்பின் வீட்டில் பற்றி அதைப் பட்சிக்கும்.", "en": "Seek the LORD , and ye shall live; lest he break out like fire in the house of Joseph, and devour it , and there be none to quench it in Beth-el."}, {"verse": 7, "start": 66.63, "end": 73.52, "ta": "நியாயத்தை எட்டியாக மாற்றி, நீதியைத் தரையிலே விழப்பண்ணுகிறவர்களே, அவரைத் தேடுங்கள்.", "en": "Ye who turn judgment to wormwood, and leave off righteousness in the earth,"}, {"verse": 8, "start": 73.52, "end": 93.26, "ta": "அவர் அறுமீனையும் மிருகசீரிஷத்தையும் உண்டாக்கினவர்; அவர் மரண இருளை விடியற்காலமாக மாற்றி பகலை இராத்திரியாக அந்தகாரப்படுத்துகிறார்; அவர் சமுத்திரத்தின் தண்ணீர்களை வரவழைத்து, அவைகளைப் பூமியின் விசாலத்தின்மேல் ஏற்றுகிறவர்; கர்த்தர் என்பது அவருடைய நாமம்.", "en": "Seek him that maketh the seven stars and Orion, and turneth the shadow of death into the morning, and maketh the day dark with night: that calleth for the waters of the sea, and poureth them out upon the face of the earth: The LORD is his name:"}, {"verse": 9, "start": 93.26, "end": 102.42, "ta": "அரணான ஸ்தலத்தின்மேல் பாழ்க்கடிப்பு வரத்தக்கதாக, அவர் கொள்ளை கொடுத்தவனைப் பலத்தவனுக்கு விரோதமாய் லகுவடையப்பண்ணுகிறவர்.", "en": "That strengtheneth the spoiled against the strong, so that the spoiled shall come against the fortress."}, {"verse": 10, "start": 102.42, "end": 109.87, "ta": "ஒலிமுகவாசலிலே கடிந்துகொள்ளுகிறவனை அவர்கள் பகைத்து, யதார்த்தமாய்ப் பேசுகிறவனை வெறுக்கிறார்கள்.", "en": "They hate him that rebuketh in the gate, and they abhor him that speaketh uprightly."}, {"verse": 11, "start": 109.87, "end": 131.1, "ta": "நீங்கள் தரித்திரனை மிதித்து, அவன் கையிலே தானியத்தைச் சுமைமையாய் வாங்குகிறபடியினால், நீங்கள் பொளிந்த கற்களால் வீடுகளைக்கட்டினீர்கள். ஆனாலும் அவைகளில் நீங்கள் குடியிருப்பதில்லை; இன்பமான திராட்சத்தோட்டங்களை நாட்டினீர்கள், ஆனாலும் அவைகளின் இரசத்தை நீங்கள் குடிப்பதில்லை.", "en": "Forasmuch therefore as your treading is upon the poor, and ye take from him burdens of wheat: ye have built houses of hewn stone, but ye shall not dwell in them; ye have planted pleasant vineyards, but ye shall not drink wine of them."}, {"verse": 12, "start": 131.1, "end": 143.88, "ta": "உங்கள் மீறுதல்கள் மிகுதியென்றும், உங்கள் பாவங்கள் பலத்ததென்றும் அறிவேன்; நீதிமானை ஒடுக்கி, பரிதானம் வாங்கி ஒலிமுகவாசலில் ஏழைகளின் நியாயத்தைப் புரட்டுகிறீர்கள்.", "en": "For I know your manifold transgressions and your mighty sins: they afflict the just, they take a bribe, and they turn aside the poor in the gate from their right ."}, {"verse": 13, "start": 143.88, "end": 151.05, "ta": "ஆகையால் புத்திமான் அந்தக் காலத்திலே மெளனமாயிருக்கவேண்டும்; அந்தக் காலம் தீமையான காலம்.", "en": "Therefore the prudent shall keep silence in that time; for it is an evil time."}, {"verse": 14, "start": 151.05, "end": 162.41, "ta": "நீங்கள் பிழைக்கும்படிக்குத் தீமையை அல்ல, நன்மையைத் தேடுங்கள்; அப்பொழுது நீங்கள் சொல்லுகிறபடியே சேனைகளின் தேவனாகிய கர்த்தர் உங்களோடே இருப்பார்.", "en": "Seek good, and not evil, that ye may live: and so the LORD , the God of hosts, shall be with you, as ye have spoken."}, {"verse": 15, "start": 162.41, "end": 175.19, "ta": "நீங்கள் தீமையை வெறுத்து நன்மையை விரும்பி, ஒலிமுகவாசலில் நியாயத்தை நிலைப்படுத்துங்கள்; ஒருவேளை சேனைகளின் தேவனாகிய கர்த்தர் யோசேப்பிலே மீதியானவர்களுக்கு இரங்குவார்.", "en": "Hate the evil, and love the good, and establish judgment in the gate: it may be that the LORD God of hosts will be gracious unto the remnant of Joseph."}, {"verse": 16, "start": 175.19, "end": 195.99, "ta": "ஆதலால் ஆண்டவரும் சேனைகளின் தேவனுமாகிய கர்த்தர் சொல்லுகிறது என்னவென்றால்: எல்லாத்தெருக்களிலும் புலம்பல் உண்டாகும்; எல்லா வீதிகளிலும் ஐயோ! ஐயோ! என்று ஓலமிடுவார்கள்; பயிரிடுகிறவர்களைத் துக்கங்கொண்டாடுகிறதற்கும், ஒப்பாரி பாட அறிந்தவர்களைப் புலம்புகிறதற்கும் வரவழைப்பார்கள்.", "en": "Therefore the LORD , the God of hosts, the Lord, saith thus; Wailing shall be in all streets; and they shall say in all the highways, Alas! alas! and they shall call the husbandman to mourning, and such as are skilful of lamentation to wailing."}, {"verse": 17, "start": 195.99, "end": 204.94, "ta": "எல்லாத் திராட்சத்தோட்டங்களிலும் புலம்பல் உண்டாயிருக்கும், நான் உன் நடுவே கடந்துபோவேன் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And in all vineyards shall be wailing: for I will pass through thee, saith the LORD ."}, {"verse": 18, "start": 204.94, "end": 215.38, "ta": "கர்த்தருடைய நாளை விரும்புகிறவர்களுக்கு ஐயோ! அதினால் உங்களுக்கு என்ன உண்டு? கர்த்தருடைய நாள் வெளிச்சமாயிராமல் அந்தகாரமாயிருக்கும்.", "en": "Woe unto you that desire the day of the LORD ! to what end is it for you? the day of the LORD is darkness, and not light."}, {"verse": 19, "start": 215.38, "end": 227.45, "ta": "சிங்கத்துக்குத் தப்பினவனுக்குக் கரடி எதிர்ப்பட்டதுபோலவும், அல்லது வீட்டுக்குள்ளே வந்து சுவரின்மேல் தன் கையை வைத்தபோது பாம்பு அவனைக் கடித்ததுபோலவும் இருக்கும்.", "en": "As if a man did flee from a lion, and a bear met him; or went into the house, and leaned his hand on the wall, and a serpent bit him."}, {"verse": 20, "start": 227.45, "end": 233.98, "ta": "கர்த்தருடைய நாள் வெளிச்சமாயிராமல், இருளும் பிரகாசமற்ற அந்தகாரமுமாயிருக்குமல்லவோ?", "en": "Shall not the day of the LORD be darkness, and not light? even very dark, and no brightness in it?"}, {"verse": 21, "start": 233.98, "end": 241.22, "ta": "உங்கள் பண்டிகைகளைப் பகைத்துவெறுக்கிறேன்; உங்கள் ஆசரிப்புநாட்களில் எனக்குப் பிரியமில்லை.", "en": "I hate, I despise your feast days, and I will not smell in your solemn assemblies."}, {"verse": 22, "start": 241.22, "end": 253.86, "ta": "உங்கள் தகனபலிகளையும் போஜனபலிகளையும் எனக்குப் படைத்தாலும் நான் அங்கீகரிக்கமாட்டேன்; கொழுமையான உங்கள் மிருகங்களின் ஸ்தோத்திரபலிகளையும் நான் நோக்கிப் பார்க்கமாட்டேன்.", "en": "Though ye offer me burnt offerings and your meat offerings, I will not accept them: neither will I regard the peace offerings of your fat beasts."}, {"verse": 23, "start": 253.86, "end": 260.89, "ta": "உன் பாட்டுகளின் இரைச்சலை என்னைவிட்டு அகற்று; உன் வீணைகளின் ஓசையை நான் கேட்கமாட்டேன்.", "en": "Take thou away from me the noise of thy songs; for I will not hear the melody of thy viols."}, {"verse": 24, "start": 260.89, "end": 266.71, "ta": "நியாயம் தண்ணீரைப்போலவும், நீதி வற்றாத நதியைப்போலவும் புரண்டுவரக்கடவது.", "en": "But let judgment run down as waters, and righteousness as a mighty stream."}, {"verse": 25, "start": 266.71, "end": 276.36, "ta": "இஸ்ரவேல் வம்சத்தாரே, நீங்கள் வனாந்தரத்திலே இருந்த நாற்பது வருஷம்வரையில் பலிகளையும் காணிக்கைகளையும் எனக்குச் செலுத்தினீர்களோ?", "en": "Have ye offered unto me sacrifices and offerings in the wilderness forty years, O house of Israel?"}, {"verse": 26, "start": 276.36, "end": 287.94, "ta": "நீங்கள் உங்களுக்கு உண்டாக்கின மோளேகுடைய கூடாரத்தையும், உங்கள் தேவர்களின் நட்சத்திர ராசியாகிய உங்கள் சொரூபங்களின் சப்பரத்தையும் சுமந்துகொண்டுவந்தீர்களே.", "en": "But ye have borne the tabernacle of your Moloch and Chiun your images, the star of your god, which ye made to yourselves."}, {"verse": 27, "start": 287.94, "end": 296.74, "ta": "ஆகையால் உங்களைத் தமஸ்குவுக்கு அப்பாலே குடியோட்டுவேன் என்று சேனைகளுடைய தேவன் என்னும் நாமமுள்ள கர்த்தர் சொல்லுகிறார்.", "en": "Therefore will I cause you to go into captivity beyond Damascus, saith the LORD , whose name is The God of hosts."}]}, "6": {"chapter": 6, "duration": 180.77, "audio_url": "audio_ot/OT30_06.mp3", "total_verses": 14, "verses": [{"verse": 1, "start": 3.8, "end": 16.52, "ta": "சீயோனிலே நிர்விசாரமாயிருக்கிறவர்களும் சமாரியாவின் பர்வதத்தை நம்பிக்கொண்டிருக்கிறவர்களும் ஜாதிகளின் தலைமையென்னப்பட்டு, இஸ்ரவேல் வம்சத்தார் தேடிவருகிறவர்களுமாகிய உங்களுக்கு ஐயோ!", "en": "Woe to them that are at ease in Zion, and trust in the mountain of Samaria, which are named chief of the nations, to whom the house of Israel came!"}, {"verse": 2, "start": 16.52, "end": 37.18, "ta": "நீங்கள் கல்னேமட்டும் சென்று, அவ்விடத்திலிருந்து ஆமாத் என்னும் பெரிய பட்டணத்துக்குப் போய், பெலிஸ்தருடைய காத் பட்டணத்துக்கு இறங்கி, அவைகள் இந்த ராஜ்யங்களைப்பார்க்கிலும் நல்லவைகளோ என்றும், அவைகளின் எல்லைகள் உங்கள் எல்லைகளைப்பார்க்கிலும் விஸ்தாரமானவைகளோ என்றும் பாருங்கள்.", "en": "Pass ye unto Calneh, and see; and from thence go ye to Hamath the great: then go down to Gath of the Philistines: be they better than these kingdoms? or their border greater than your border?"}, {"verse": 3, "start": 37.18, "end": 42.11, "ta": "தீங்குநாள் தூரமென்றெண்ணிக் கொடுமையின் ஆசனம் கிட்டிவரும்படி செய்து,", "en": "Ye that put far away the evil day, and cause the seat of violence to come near;"}, {"verse": 4, "start": 42.11, "end": 55.19, "ta": "தந்தக் கட்டில்களில் படுத்துக்கொண்டு, தங்கள் மஞ்சங்களின்மேல் சவுக்கியமாய்ச் சயனித்து, மந்தையிலுள்ள ஆட்டுக்குட்டிகளையும், மாட்டுத்தொழுவத்திலுள்ள கன்றுக்குட்டிகளையும் தின்று,", "en": "That lie upon beds of ivory, and stretch themselves upon their couches, and eat the lambs out of the flock, and the calves out of the midst of the stall;"}, {"verse": 5, "start": 55.19, "end": 61.19, "ta": "தம்புரை வாசித்துப் பாடி, தாவீதைப்போல் கீதவாத்தியங்களைத் தங்களுக்கு உண்டுபண்ணி,", "en": "That chant to the sound of the viol, and invent to themselves instruments of musick, like David;"}, {"verse": 6, "start": 61.19, "end": 73.63, "ta": "பெரிய பாத்திரங்களில் மதுபானத்தைக் குடித்து, சிறந்த பரிமளதைலங்களைப் பூசிக்கொள்ளுகிறார்கள்; ஆனாலும் யோசேப்புக்கு நேரிட்ட ஆபத்துக்குக் கவலைப்படாமற்போகிறார்கள்.", "en": "That drink wine in bowls, and anoint themselves with the chief ointments: but they are not grieved for the affliction of Joseph."}, {"verse": 7, "start": 73.63, "end": 84.71, "ta": "ஆகையால் அவர்கள் சிறையிருப்புக்குப் போகிறவர்களின் முன்னணியிலே போவார்கள்; இப்படியே செல்வமாய்ச் சயனித்தவர்களின் விருந்துகொண்டாடல் நின்றுபோகும்.", "en": "Therefore now shall they go captive with the first that go captive, and the banquet of them that stretched themselves shall be removed."}, {"verse": 8, "start": 84.71, "end": 103.01, "ta": "நான் யாக்கோபுடைய மேன்மையை வெறுத்து, அவனுடைய அரமனைகளைப் பகைக்கிறேன்; நான் நகரத்தையும் அதின் நிறைவையும் ஒப்புக்கொடுத்துவிடுவேன் என்று கர்த்தராகிய ஆண்டவர் தம்முடைய ஜீவனைக் கொண்டு ஆணையிட்டார் என்பதைச் சேனைகளின் தேவனாகிய கர்த்தர் சொல்லுகிறார்.", "en": "The Lord GOD hath sworn by himself, saith the LORD the God of hosts, I abhor the excellency of Jacob, and hate his palaces: therefore will I deliver up the city with all that is therein."}, {"verse": 9, "start": 103.01, "end": 108.65, "ta": "ஒரு வீட்டிலே பத்துப்பேர் மீதியாயிருந்தாலும் அவர்கள் செத்துப்போவார்கள்.", "en": "And it shall come to pass, if there remain ten men in one house, that they shall die."}, {"verse": 10, "start": 108.65, "end": 132.74, "ta": "அவர்களுடைய இனத்தானாவது, பிரேதத்தைத் தகிக்கிறவனாவது எலும்புகளை வீட்டிலிருந்துவெளியேகொண்டுபோகும்படிக்கு, அவைகளை எடுத்து வீட்டின் உட்புறத்திலே இருக்கிறவனை நோக்கி: உன்னிடத்தில் இன்னும் யாராயினும் உண்டோ என்று கேட்பான், அவன் இல்லையென்பான்; அப்பொழுது இவன்: நீ மெளனமாயிரு; கர்த்தருடைய நாமத்தைச் சொல்லலாகாது என்பான்.", "en": "And a man’s uncle shall take him up, and he that burneth him, to bring out the bones out of the house, and shall say unto him that is by the sides of the house, Is there yet any with thee? and he shall say, No. Then shall he say, Hold thy tongue: for we may not make mention of the name of the LORD ."}, {"verse": 11, "start": 132.74, "end": 141.89, "ta": "இதோ கர்த்தர் கட்டளையிட்டிருக்கிறார்; பெரிய வீட்டைத் திறப்புகள் உண்டாகவும், சிறிய வீடுகள் உண்டாகவும் அடிப்பார்.", "en": "For, behold, the LORD commandeth, and he will smite the great house with breaches, and the little house with clefts."}, {"verse": 12, "start": 141.89, "end": 153.47, "ta": "ஒரு கன்மலையின்மேல் குதிரைகள் ஓடுமோ? அங்கே ஒருவன் மாடுகளால் உழுவானோ? நியாயத்தை நஞ்சாகவும், நீதியின் கனியை எட்டியாகவும் மாற்றினீர்கள்.", "en": "Shall horses run upon the rock? will one plow there with oxen? for ye have turned judgment into gall, and the fruit of righteousness into hemlock:"}, {"verse": 13, "start": 153.47, "end": 162.54, "ta": "நாங்கள் எங்கள் பலத்தினாலே எங்களுக்குக் கொம்புகளை உண்டாக்கிக்கொள்ளவில்லையோ என்று சொல்லி வீண்காரியத்தில் மகிழுகிறார்கள்.", "en": "Ye which rejoice in a thing of nought, which say, Have we not taken to us horns by our own strength?"}, {"verse": 14, "start": 162.54, "end": 179.27, "ta": "இஸ்ரவேல் வம்சத்தாரே, இதோ நான் ஒரு ஜாதியை உங்களுக்கு விரோதமாக எழுப்புவேன்; அவர்கள் ஆமாத்துக்குள் பிரவேசிக்கிற வழிதொடங்கிச் சமனான நாட்டின் ஆறுமட்டாக உங்களை ஒடுக்குவார்கள் என்று சேனைகளின் தேவனாகிய கர்த்தர் சொல்லுகிறார்.", "en": "But, behold, I will raise up against you a nation, O house of Israel, saith the LORD the God of hosts; and they shall afflict you from the entering in of Hemath unto the river of the wilderness."}]}, "7": {"chapter": 7, "duration": 215.27, "audio_url": "audio_ot/OT30_07.mp3", "total_verses": 17, "verses": [{"verse": 1, "start": 3.8, "end": 16.84, "ta": "கர்த்தராகிய ஆண்டவர் எனக்குக் காண்பித்ததாவது: இதோ, ராஜாவினுடைய புல்லறுப்புக்குப்பின்பு இரண்டாம் கந்தாயத்துப் புல் முளைக்கத் தொடங்குகையில் அவர் வெட்டுக்கிளிகளை உண்டாக்கினார்.", "en": "Thus hath the Lord GOD shewed unto me; and, behold, he formed grasshoppers in the beginning of the shooting up of the latter growth; and, lo, it was the latter growth after the king’s mowings."}, {"verse": 2, "start": 16.84, "end": 29.96, "ta": "அவைகள் தேசத்தின் புல்லைத்தின்று தீர்ந்தபோது, நான்: கர்த்தராகிய ஆண்டவரே மன்னித்தருளும்; யாக்கோபு திரும்ப யாராலே எழுந்திருப்பான்? அவன் சிறுத்துப்போனான் என்றேன்.", "en": "And it came to pass, that when they had made an end of eating the grass of the land, then I said, O Lord GOD , forgive, I beseech thee: by whom shall Jacob arise? for he is small."}, {"verse": 3, "start": 29.96, "end": 34.78, "ta": "கர்த்தர் அதற்கு மனஸ்தாபப்பட்டு, அப்படி ஆவதில்லை என்றார்.", "en": "The LORD repented for this: It shall not be, saith the LORD ."}, {"verse": 4, "start": 34.78, "end": 49.66, "ta": "கர்த்தராகிய ஆண்டவர் எனக்குக் காண்பித்ததாவது: இதோ, அக்கினியாலே நியாயம் விசாரிப்பேன் என்று கர்த்தராகிய ஆண்டவர் ஏற்பட்டார்; அது மகா ஆழியைப் பட்சித்தது, அதில் ஒரு பங்கைப் பட்சித்துத் தீர்ந்தது.", "en": "Thus hath the Lord GOD shewed unto me: and, behold, the Lord GOD called to contend by fire, and it devoured the great deep, and did eat up a part."}, {"verse": 5, "start": 49.66, "end": 60.09, "ta": "அப்பொழுது நான்: கர்த்தராகிய ஆண்டவரே, நிறுத்துமே; யாக்கோபு திரும்ப யாராலே எழுந்திருப்பான்? அவன் சிறுத்துப்போனான் என்றேன்.", "en": "Then said I, O Lord GOD , cease, I beseech thee: by whom shall Jacob arise? for he is small."}, {"verse": 6, "start": 60.09, "end": 64.91, "ta": "கர்த்தர் அதற்கு மனஸ்தாபப்பட்டு, அப்படி ஆவதில்லை என்றார்.", "en": "The LORD repented for this: This also shall not be, saith the Lord GOD ."}, {"verse": 7, "start": 64.91, "end": 75.61, "ta": "பின்பு அவர் எனக்குக் காண்பித்ததாவது: இதோ தூக்குநூல் பிரமாணத்தினால் கட்டப்பட்ட ஒரு மதிலின்மேல் நின்றார்; அவர் கையில் தூக்குநூல் இருந்தது.", "en": "Thus he shewed me: and, behold, the Lord stood upon a wall made by a plumbline, with a plumbline in his hand."}, {"verse": 8, "start": 75.61, "end": 92.27, "ta": "கர்த்தர் என்னை நோக்கி: ஆமோசே, நீ என்னத்தைக் காண்கிறாய் என்றார்; தூக்நூலைக் காண்கிறேன் என்றேன்; அப்பொழுது ஆண்டவர்: இதோ, இஸ்ரவேலென்னும் என்ஜனத்தின் நடுவே தூக்குநூலை விடுவேன்; இனி அவர்களை மன்னிக்கமாட்டேன்.", "en": "And the LORD said unto me, Amos, what seest thou? And I said, A plumbline. Then said the Lord, Behold, I will set a plumbline in the midst of my people Israel: I will not again pass by them any more:"}, {"verse": 9, "start": 92.27, "end": 104.46, "ta": "ஈசாக்கின் மேடைகள் பாழும், இஸ்ரவேலின் பரிசுத்த ஸ்தலங்கள் அவாந்தரமுமாக்கப்படும்; நான் எரொபெயாம் வீட்டாருக்கு விரோதமாய்ப் பட்டயத்தோடே எழும்பிவருவேன் என்றார்.", "en": "And the high places of Isaac shall be desolate, and the sanctuaries of Israel shall be laid waste; and I will rise against the house of Jeroboam with the sword."}, {"verse": 10, "start": 104.46, "end": 120.13, "ta": "அப்பொழுது பெத்தேலில் ஆசாரியனான அத்சியா இஸ்ரவேலின் ராஜாவாகிய எரொபெயாமுக்கு அனுப்பி: ஆமோஸ் இஸ்ரவேல் வம்சத்தாரின் நடுவே உமக்கு விரோதமாகக் கட்டுப்பாடு பண்ணுகிறான்; தேசம் அவன் வார்த்தைகளையெல்லாம் சகிக்கமாட்டாது.", "en": "Then Amaziah the priest of Beth-el sent to Jeroboam king of Israel, saying, Amos hath conspired against thee in the midst of the house of Israel: the land is not able to bear all his words."}, {"verse": 11, "start": 120.13, "end": 131.61, "ta": "எரோபேயாம் பட்டயத்தினால் சாவான் என்றும், இஸ்ரவேல் தன்தேசத்திலிருந்து சிறைபிடித்துக்கொண்டுபோகப்படுவான் என்றும் ஆமோஸ் சொல்லுகிறான் என்று சொல்லச்சொன்னான்.", "en": "For thus Amos saith, Jeroboam shall die by the sword, and Israel shall surely be led away captive out of their own land."}, {"verse": 12, "start": 131.61, "end": 142.24, "ta": "அமத்சியா ஆமோசை நோக்கி: தரிசனம் பார்க்கிறவனே, போ; நீ யூதாதேசத்துக்கு ஓடிப்போ, அங்கே அப்பம் தின்று, அங்கே தீர்க்கதரிசனம் சொல்லு.", "en": "Also Amaziah said unto Amos, O thou seer, go, flee thee away into the land of Judah, and there eat bread, and prophesy there:"}, {"verse": 13, "start": 142.24, "end": 151.39, "ta": "பெத்தேலிலே இனித் தீர்க்கதரிசனம் சொல்லாதே; அது ராஜாவின் பரிசுத்த ஸ்தலமும் ராஜ்யத்தின் அரமனையுமாயிருக்கிறது என்றான்.", "en": "But prophesy not again any more at Beth-el: for it is the king’s chapel, and it is the king’s court."}, {"verse": 14, "start": 151.39, "end": 165.0, "ta": "ஆமோஸ் அமத்சியாவுக்குப் பிரதியுத்தரமாக: நான் தீர்க்கதரிசியுமல்ல, தீர்க்கதரிசியின் புத்திரனுமல்ல; நான் மந்தை மேய்க்கிறவனும், காட்டத்திப்பழங்களைப் பொறுக்குகிறவனுமாயிருந்தேன்.", "en": "Then answered Amos, and said to Amaziah, I was no prophet, neither was I a prophet’s son; but I was an herdman, and a gatherer of sycomore fruit:"}, {"verse": 15, "start": 165.0, "end": 176.62, "ta": "ஆனால் மந்தையின் பின்னாலே போகிறபோது என்னைக் கர்த்தர் அழைத்து, நீ போய் என் ஜனமாகிய இஸ்ரவேலுக்கு விரோதமாகத் தீர்க்கதரிசனம் சொல்லு என்று கர்த்தர் உரைத்தார்.", "en": "And the LORD took me as I followed the flock, and the LORD said unto me, Go, prophesy unto my people Israel."}, {"verse": 16, "start": 176.62, "end": 189.67, "ta": "இப்போதும் நீ கர்த்தருடைய வார்த்தையைக் கேள்; இஸ்ரவேலுக்கு விரோதமாய்த் தீர்க்கதரிசனம் சொல்லாதே, ஈசாக்கின் வம்சத்தாருக்கு விரோதமாக ஒன்றையும் சொல்லாதே என்று சொல்லுகிறாயே.", "en": "Now therefore hear thou the word of the LORD : Thou sayest, Prophesy not against Israel, and drop not thy word against the house of Isaac."}, {"verse": 17, "start": 189.67, "end": 213.77, "ta": "இதினிமித்தம்: உன் பெண்ஜாதி நகரத்தில் வேசியாவாள்; உன் குமாரரும் உன் குமாரத்திகளும் பட்டயத்தால் விழுவார்கள்; உன் வயல் அளவு நூலால் பங்கிட்டுக்கொள்ளப்படும்; நீயாவெனில் அசுத்தமான தேசத்திலே செத்துப்போவாய்; இஸ்ரவேலும் தன் தேசத்திலிருந்து சிறைபிடிக்கப்பட்டுக் கொண்டுபோகப்படுவான் என்று கர்த்தர் சொல்லுகிறார் என்றான்.", "en": "Therefore thus saith the LORD ; Thy wife shall be an harlot in the city, and thy sons and thy daughters shall fall by the sword, and thy land shall be divided by line; and thou shalt die in a polluted land: and Israel shall surely go into captivity forth of his land."}]}, "8": {"chapter": 8, "duration": 185.32, "audio_url": "audio_ot/OT30_08.mp3", "total_verses": 14, "verses": [{"verse": 1, "start": 3.8, "end": 11.52, "ta": "பின்பு கர்த்தராகிய ஆண்டவர் எனக்குக் காண்பித்ததாவது: இதோ, பழுத்த பழங்களுள்ள ஒரு கூடை இருந்தது.", "en": "Thus hath the Lord GOD shewed unto me: and behold a basket of summer fruit."}, {"verse": 2, "start": 11.52, "end": 29.74, "ta": "அவர்: ஆமோசே, நீ என்னத்தைக் காண்கிறாய் என்று கேட்டார்? பழுத்த பழங்களுள்ள ஒரு கூடையைக் காண்கிறேன் என்றேன். அப்பொழுது கர்த்தர் என்னை நோக்கி: என் ஜனமாகிய இஸ்ரவேலுக்கு முடிவுகாலம் வந்தது; இனி அவர்களை மன்னிக்கமாட்டேன்.", "en": "And he said, Amos, what seest thou? And I said, A basket of summer fruit. Then said the LORD unto me, The end is come upon my people of Israel; I will not again pass by them any more."}, {"verse": 3, "start": 29.74, "end": 42.08, "ta": "அந்நாளிலே தேவாலயப்பாட்டுகள் அலறுதலாக மாறும்; எல்லா இடத்திலும் திரளான பிரேதங்கள் புலம்பலில்லாமல் எறிந்துவிடப்படும் என்று கர்த்தராகிய ஆண்டவர் சொல்லுகிறார்.", "en": "And the songs of the temple shall be howlings in that day, saith the Lord GOD : there shall be many dead bodies in every place; they shall cast them forth with silence."}, {"verse": 4, "start": 42.08, "end": 47.0, "ta": "தேசத்தில் சிறுமைப்பட்டவர்களை ஒழியப்பண்ண, எளியவர்களை விழுங்கி,", "en": "Hear this, O ye that swallow up the needy, even to make the poor of the land to fail,"}, {"verse": 5, "start": 47.0, "end": 62.88, "ta": "நாங்கள் மரக்காலைக் குறைத்து, சேக்கல் நிறையை அதிகமாக்கி, கள்ளத்தராசினால் வஞ்சித்து, தரித்திரரைப் பணத்துக்கும், எளியவர்களை ஒருஜோடு பாதரட்சைக்கும் கொள்ளும்படிக்கும், தானியத்தின் பதரை விற்கும்படிக்கும்,", "en": "Saying, When will the new moon be gone, that we may sell corn? and the sabbath, that we may set forth wheat, making the ephah small, and the shekel great, and falsifying the balances by deceit?"}, {"verse": 6, "start": 62.88, "end": 75.66, "ta": "நாங்கள் தவசம் விற்கத்தக்கதாக மாதப்பிறப்பும், நாங்கள் தானியத்தின் பண்டசாலைகளைத் திறக்கத்தக்கதாக ஓய்வுநாளும் எப்போது முடியும் என்று சொல்லுகிறவர்களே இதைக் கேளுங்கள்.", "en": "That we may buy the poor for silver, and the needy for a pair of shoes; yea , and sell the refuse of the wheat?"}, {"verse": 7, "start": 75.66, "end": 84.26, "ta": "அவர்கள் செய்கைகளையெல்லாம் நான் ஒருபோதும் மறப்பதில்லையென்று கர்த்தர் யாக்கோபுடைய மகிமையின்பேரில் ஆணையிட்டார்.", "en": "The LORD hath sworn by the excellency of Jacob, Surely I will never forget any of their works."}, {"verse": 8, "start": 84.26, "end": 97.92, "ta": "இதினிமித்தம் தேசம் அதிரவும், அதின் குடிகள் எல்லாம் துக்கிக்கவும், எங்கும் நதிகளாய்ப் புரண்டோடவும், எகிப்தின் ஆற்றுவெள்ளத்தைப்போல் அடித்து, பெருவெள்ளமாகவும் வேண்டாமோ?", "en": "Shall not the land tremble for this, and every one mourn that dwelleth therein? and it shall rise up wholly as a flood; and it shall be cast out and drowned, as by the flood of Egypt."}, {"verse": 9, "start": 97.92, "end": 104.98, "ta": "அந்நாளிலே நான் மத்தியானத்திலே சூரியனை அஸ்தமிக்கப்பண்ணி பட்டப்பகலிலே தேசத்தை அந்தகாரப்படுத்தி,", "en": "And it shall come to pass in that day, saith the Lord GOD , that I will cause the sun to go down at noon, and I will darken the earth in the clear day:"}, {"verse": 10, "start": 104.98, "end": 129.59, "ta": "உங்கள் பண்டிகைகளைத் துக்கிப்பாகவும், உங்கள் பாட்டுகளையெல்லாம் புலம்பலாகவும் மாறப்பண்ணி, சகல அரைகளிலும் இரட்டையும், சகல தலைகளிலும் மொட்டையையும் வருவித்து அவர்களுடைய துக்கிப்பை ஒரே பிள்ளைக்காகத் துக்கிக்கிற துக்கிப்புக்குச் சமானமாக்கி, அவர்களுடைய முடிவைக் கசப்பான நாளாக்குவேன் என்று கர்த்தராகிய ஆண்டவர் சொல்லுகிறார்.", "en": "And I will turn your feasts into mourning, and all your songs into lamentation; and I will bring up sackcloth upon all loins, and baldness upon every head; and I will make it as the mourning of an only son , and the end thereof as a bitter day."}, {"verse": 11, "start": 129.59, "end": 147.82, "ta": "இதோ, நான் தேசத்தின்மேல் பஞ்சத்தை அனுப்பும் நாட்கள் வரும்; ஆகாரக் குறைவினால் உண்டாகிய பஞ்சமல்ல, ஜலக்குறைவினால் உண்டாகிய தாகமுமல்ல, கர்த்தருடைய வசனம் கேட்கக் கிடையாத பஞ்சத்தை அனுப்புவேன் என்று கர்த்தராகிய ஆண்டவர் சொல்லுகிறார்.", "en": "Behold, the days come, saith the Lord GOD , that I will send a famine in the land, not a famine of bread, nor a thirst for water, but of hearing the words of the LORD :"}, {"verse": 12, "start": 147.82, "end": 161.04, "ta": "அப்பொழுது அவர்கள் கர்த்தருடைய வசனத்தைத் தேட ஒரு சமுத்திரந்தொடங்கி மறு சமுத்திரமட்டும், வடதிசைதொடங்கிக் கீழ்த்திசைமட்டும் அலைந்து திரிந்தும் அதைக் கண்டடையாமற் போவார்கள்.", "en": "And they shall wander from sea to sea, and from the north even to the east, they shall run to and fro to seek the word of the LORD , and shall not find it ."}, {"verse": 13, "start": 161.04, "end": 167.43, "ta": "அந்நாளிலே செளந்தரியமுள்ள கன்னிகைகளும் வாலிபரும் தாகத்தினால் சோர்ந்துபோவார்கள்.", "en": "In that day shall the fair virgins and young men faint for thirst."}, {"verse": 14, "start": 167.43, "end": 183.82, "ta": "தாணே! உன் தேவனுடைய ஜீவனைக்கொண்டும், பெயெர்செபா மார்க்கத்தின் தேவனுடைய ஜீவனைக்கொண்டும் என்று சொல்லி, சமாரியாவின் தோஷத்தின்மேல் ஆணையிடுகிறவர்கள் விழுவார்கள்; இனி ஒருபோதும் எழுந்திருக்கமாட்டார்கள் என்றார்.", "en": "They that swear by the sin of Samaria, and say, Thy god, O Dan, liveth; and, The manner of Beer-sheba liveth; even they shall fall, and never rise up again."}]}, "9": {"chapter": 9, "duration": 235.63, "audio_url": "audio_ot/OT30_09.mp3", "total_verses": 15, "verses": [{"verse": 1, "start": 3.8, "end": 29.81, "ta": "ஆண்டவரைப் பலிபீடத்தின்மேல் நிற்கக்கண்டேன்; அவர்: நீ வாசல் நிலைகள் அசையும்படி போதிகையை அடித்து, அவைகளை அவர்கள் எல்லாருடைய தலையின்மேலும் விழ உடைத்துப்போடு; அவர்களுக்குப் பின்னாகவரும் மீதியானவர்களை நான் பட்டயத்தினால் கொன்றுபோடுவேன்; அவர்களில் ஓடுகிறவன் ஒருவனும் தப்புவதுமில்லை, அவர்களில் தப்புகிறவன் ஒருவனும் இரட்சிக்கப்படுவதுமில்லை.", "en": "I saw the Lord standing upon the altar: and he said, Smite the lintel of the door, that the posts may shake: and cut them in the head, all of them; and I will slay the last of them with the sword: he that fleeth of them shall not flee away, and he that escapeth of them shall not be delivered."}, {"verse": 2, "start": 29.81, "end": 44.42, "ta": "அவர்கள் பாதாளபரியந்தம் தோண்டிப் பதுங்கிக்கொண்டாலும், என் கை அவ்விடத்திலிருந்து அவர்களைப் பிடித்துக்கொண்டுவரும்; அவர்கள் வானபரியந்தம் ஏறினாலும் அவ்விடத்திலுமிருந்து அவர்களை இறங்கப்பண்ணுவேன்;", "en": "Though they dig into hell, thence shall mine hand take them; though they climb up to heaven, thence will I bring them down:"}, {"verse": 3, "start": 44.42, "end": 61.19, "ta": "அவர்கள் கர்மேலின் கொடுமுடியிலே ஒளித்துக்கொண்டாலும், அங்கே அவர்களைத் தேடிப்பிடிப்பேன்; அவர்கள் சமுத்திரத்தின் ஆழத்திலே போய் என் கண்களுக்கு மறைந்துகொண்டாலும், அங்கே அவர்களைக் கடிக்கப் பாம்புகளுக்குக் கட்டளையிடுவேன்.", "en": "And though they hide themselves in the top of Carmel, I will search and take them out thence; and though they be hid from my sight in the bottom of the sea, thence will I command the serpent, and he shall bite them:"}, {"verse": 4, "start": 61.19, "end": 75.37, "ta": "அவர்கள் தங்கள் சத்துருவுக்கு முன்பாகச் சிறைப்பட்டுப்போனாலும், அங்கே அவைகளைக் கொன்றுபோடப் பட்டயத்துக்கு நான் கட்டளையிட்டு, என் கண்களை அவர்கள்மேல் நன்மைக்கல்ல, தீமைக்கென்றே வைப்பேன்.", "en": "And though they go into captivity before their enemies, thence will I command the sword, and it shall slay them: and I will set mine eyes upon them for evil, and not for good."}, {"verse": 5, "start": 75.37, "end": 90.06, "ta": "சேனைகளின் கர்த்தராகிய ஆண்டவர் தேசத்தைத் தொட அது உருகிப்போம்; அப்பொழுது அதின் குடிகளெல்லாரும் புலம்புவார்கள்; எங்கும் நதியாய்ப் புரண்டோடி எகிப்தினுடைய ஆற்று வெள்ளத்தைப்போல் வெள்ளமாகும்.", "en": "And the Lord GOD of hosts is he that toucheth the land, and it shall melt, and all that dwell therein shall mourn: and it shall rise up wholly like a flood; and shall be drowned, as by the flood of Egypt."}, {"verse": 6, "start": 90.06, "end": 105.96, "ta": "அவர் வானத்தில் தமது மேலறைகளைக் கட்டி, பூமியில் தமது கீழறைகளை அஸ்திபாரப்படுத்தி, சமுத்திரத்தின் தண்ணீர்களை வரவழைத்து, அவர்களைப் பூமியினுடைய விசாலத்தின்மேல் ஊற்றுகிறவர்; கர்த்தர் என்பது அவருடைய நாமம்.", "en": "It is he that buildeth his stories in the heaven, and hath founded his troop in the earth; he that calleth for the waters of the sea, and poureth them out upon the face of the earth: The LORD is his name."}, {"verse": 7, "start": 105.96, "end": 124.3, "ta": "இஸ்ரவேல் புத்திரரே, நீங்கள் எனக்கு எத்தியோப்பியரின் புத்திரரைப்போல் இருக்கிறீர்கள் அல்லவோ என்று கர்த்தர் சொல்லுகிறார்; நான் இஸ்ரவேலை எகிப்துதேசத்திலிருந்தும், பெலிஸ்தரைக் கப்தோரிலிருந்தும், சீரியரைக் கீரிலிருந்தும் கொண்டுவரவில்லையோ?", "en": "Are ye not as children of the Ethiopians unto me, O children of Israel? saith the LORD . Have not I brought up Israel out of the land of Egypt? and the Philistines from Caphtor, and the Syrians from Kir?"}, {"verse": 8, "start": 124.3, "end": 141.21, "ta": "கர்த்தராகிய ஆண்டவரின் கண்கள் பாவமுள்ள ராஜ்யத்துக்கு விரோதமாக வைக்கப்பட்டிருக்கிறது; அதைப் பூமியின்மேல் இராதபடிக்கு அழித்துப்போடுவேன்; ஆகிலும் யாக்கோபின் வம்சத்தை முழுவதும் அழிக்கமாட்டேன் என்று கர்த்தர் சொல்லுகிறார்.", "en": "Behold, the eyes of the Lord GOD are upon the sinful kingdom, and I will destroy it from off the face of the earth; saving that I will not utterly destroy the house of Jacob, saith the LORD ."}, {"verse": 9, "start": 141.21, "end": 154.75, "ta": "இதோ, ஜல்லடையினால் சலித்தரிக்கிறதுபோல் இஸ்ரவேல் வம்சத்தாரை எல்லா ஜாதிகளுக்குள்ளும் சலித்தரிக்கும்படிக்கு நான் கட்டளையிடுவேன்; ஆனாலும் ஒரு கோதுமைமணியும் தரையிலே விழுவதில்லை.", "en": "For, lo, I will command, and I will sift the house of Israel among all nations, like as corn is sifted in a sieve, yet shall not the least grain fall upon the earth."}, {"verse": 10, "start": 154.75, "end": 164.64, "ta": "தீங்கு எங்களை அணுகுவதுமில்லை, எங்களுக்கு நேரிடுவதுமில்லையென்று என் ஜனத்தில் சொல்லுகிற பாவிகளெல்லாரும் பட்டயத்தினால் சாவார்கள்.", "en": "All the sinners of my people shall die by the sword, which say, The evil shall not overtake nor prevent us."}, {"verse": 11, "start": 164.64, "end": 171.08, "ta": "ஏதோமில் மீதியானவர்களையும் என் நாமம் விளங்கிய சகல ஜாதிகளையும் வசமாக்கிக்கொள்ளும்படிக்கு,", "en": "In that day will I raise up the tabernacle of David that is fallen, and close up the breaches thereof; and I will raise up his ruins, and I will build it as in the days of old:"}, {"verse": 12, "start": 171.08, "end": 187.63, "ta": "அந்நாளிலே விழுந்துபோன தாவீதின் கூடாரத்தை நான் திரும்ப எடுப்பித்து, அதின் திறப்புகளை அடைத்து, அதில் பழுதாய்ப்போனதைச் சீர்ப்படுத்தி, பூர்வநாட்களிலிருந்ததுபோல அதை ஸ்தாபிப்பேனென்று இதைச் செய்கிற கர்த்தர் சொல்லுகிறார்.", "en": "That they may possess the remnant of Edom, and of all the heathen, which are called by my name, saith the LORD that doeth this."}, {"verse": 13, "start": 187.63, "end": 203.4, "ta": "இதோ உழுகிறவன் அறுக்கிறவனையும், திராட்சப்பழங்களை ஆலையாடுகிறவன் விதைக்கிறவனையும் தொடர்ந்துபிடித்து, பர்வதங்கள் திராட்சரசமாய் வடிகிறதும், மேடுகளெல்லாம் கரைகிறதுமான நாட்கள்வரும் என்று கர்த்தர் சொல்லுகிறார்.", "en": "Behold, the days come, saith the LORD , that the plowman shall overtake the reaper, and the treader of grapes him that soweth seed; and the mountains shall drop sweet wine, and all the hills shall melt."}, {"verse": 14, "start": 203.4, "end": 221.31, "ta": "என் ஜனமாகிய இஸ்ரவேலின் சிறையிருப்பைத் திருப்புவேன்; அவர்கள் பாழான நகரங்களைக் கட்டி, அவைகளில் குடியிருந்து, திராட்சத்தோட்டங்களை நாட்டி, அவைகளுடைய பழரசத்தைக் குடித்து, தோட்டங்களை உண்டாக்கி, அவைகளின் கனிகளைப் புசிப்பார்கள்.", "en": "And I will bring again the captivity of my people of Israel, and they shall build the waste cities, and inhabit them; and they shall plant vineyards, and drink the wine thereof; they shall also make gardens, and eat the fruit of them."}, {"verse": 15, "start": 221.31, "end": 234.13, "ta": "அவர்களை அவர்கள் தேசத்திலே நாட்டுவேன்; நான் அவர்களுக்குக் கொடுத்த தேசத்திலிருந்து அவர்கள் இனிப் பிடுங்கப்படுவதில்லையென்று உன் தேவனாகிய கர்த்தர் சொல்லுகிறார் என்றார்.", "en": "And I will plant them upon their land, and they shall no more be pulled up out of their land which I have given them, saith the LORD thy God."}]}}});
} else {
  window.BIBLE_CACHE = window.BIBLE_CACHE || {};
  window.BIBLE_CACHE['30'] = {"id": 30, "testament": "OT", "code": "AMO", "name_en": "Amos", "name_ta": "ஆமோஸ்", "category": "Minor Prophets", "category_ta": "சிறிய தீர்க்கதரிசிகள்", "total_chapters": 9, "chapters": {"1": {"chapter": 1, "duration": 211.86, "audio_url": "audio_ot/OT30_01.mp3", "total_verses": 15, "verses": [{"verse": 1, "start": 4.8, "end": 24.45, "ta": "தெக்கோவா ஊர் மேய்ப்பருக்குள் இருந்த ஆமோஸ், யூதாவின் ராஜாவாகிய உசியாவின் நாட்களிலும், இஸ்ரவேலின் ராஜாவாகிய யோவாசுடைய குமாரனாகிய எரொபெயாமின் நாட்களிலும், பூமி அதிர்ச்சி உண்டாக இரண்டு வருஷத்துக்கு முன்னே, இஸ்ரவேலைக்குறித்துத் தரிசனங்கண்டு சொன்ன வார்த்தைகள்.", "en": "The words of Amos, who was among the herdmen of Tekoa, which he saw concerning Israel in the days of Uzziah king of Judah, and in the days of Jeroboam the son of Joash king of Israel, two years before the earthquake."}, {"verse": 2, "start": 24.45, "end": 37.31, "ta": "கர்த்தர் சீயோனிலிருந்து கெர்ச்சித்து, எருசலேமிலிருந்து சத்தமிடுவார்; அதினால் மேய்ப்பரின் தாபரங்கள் துக்கங்கொண்டாடும்; கர்மேலின் கொடுமுடியும் காய்ந்துபோகும்.", "en": "And he said, The LORD will roar from Zion, and utter his voice from Jerusalem; and the habitations of the shepherds shall mourn, and the top of Carmel shall wither."}, {"verse": 3, "start": 37.31, "end": 53.1, "ta": "கர்த்தர் சொல்லுகிறது என்னவென்றால்: தமஸ்குவினுடைய மூன்று பாதகங்களினிமித்தமும், நாலு பாதகங்களினிமித்தமும், நான் அதின் ஆக்கினையைத் திருப்பமாட்டேன்; அவர்கள் கீலேயாத்தை இருப்புக் கருவிகளினால் அடித்தார்களே.", "en": "Thus saith the LORD ; For three transgressions of Damascus, and for four, I will not turn away the punishment thereof; because they have threshed Gilead with threshing instruments of iron:"}, {"verse": 4, "start": 53.1, "end": 59.6, "ta": "ஆசகேலின் வீட்டிலே தீக்கொளுத்துவேன்; அது பெனாதாத்தின் அரமனைகளைப் பட்சிக்கும்.", "en": "But I will send a fire into the house of Hazael, which shall devour the palaces of Ben-hadad."}, {"verse": 5, "start": 59.6, "end": 78.18, "ta": "நான் தமஸ்குவின் தாழப்பாளை உடைத்து, குடிகளை ஆவேன் என்னும் பள்ளத்தாக்கிலும், செங்கோல் செலுத்துகிறவனைப் பெத்எதேனிலும் இராதபடிக்குச் சங்காரம்பண்ணுவேன்; அப்பொழுது சீரியாவின் ஜனங்கள் கீருக்குச் சிறைப்பட்டுப்போவார்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "I will break also the bar of Damascus, and cut off the inhabitant from the plain of Aven, and him that holdeth the sceptre from the house of Eden: and the people of Syria shall go into captivity unto Kir, saith the LORD ."}, {"verse": 6, "start": 78.18, "end": 96.04, "ta": "கர்த்தர் சொல்லுகிறது என்னவென்றால்: காத்சாவினுடைய மூன்று பாதங்களினிமித்தமும், நாலு பாதகங்களினிமித்தமும், நான் அதின் ஆக்கினையைத் திருப்பமாட்டேன்; அவர்கள் சிறைப்பட்டவர்களை ஏதோமியரிடத்தில் ஒப்புவிக்கும்படி முழுதும் சிறையாக்கினார்களே.", "en": "Thus saith the LORD ; For three transgressions of Gaza, and for four, I will not turn away the punishment thereof; because they carried away captive the whole captivity, to deliver them up to Edom:"}, {"verse": 7, "start": 96.04, "end": 102.54, "ta": "காத்சாவின் மதிலுக்குள் தீக்கொளுத்துவேன்; அது அதினுடைய அரமனைகளைப் பட்சிக்கும.", "en": "But I will send a fire on the wall of Gaza, which shall devour the palaces thereof:"}, {"verse": 8, "start": 102.54, "end": 118.69, "ta": "நான் குடிகளை அஸ்தோத்திலும், செங்கோல் செலுத்துகிறவனை அஸ்கலோனிலும் இராதபடிக்குச் சங்காரம்பண்ணி, பெலிஸ்தரில் மீதியானவர்கள் அழியும்படிக்கு என் கையை எனக்கு விரோதமாகத திருப்புவேனென்று கர்த்தராகிய ஆண்டவர் சொல்லுகிறார்.", "en": "And I will cut off the inhabitant from Ashdod, and him that holdeth the sceptre from Ashkelon, and I will turn mine hand against Ekron: and the remnant of the Philistines shall perish, saith the Lord GOD ."}, {"verse": 9, "start": 118.69, "end": 135.7, "ta": "மேலும்: தீருவினுடைய மூன்று பாதகங்களினிமித்தமும், நாலு பாதகங்களினிமித்தமும், நான் அதின் ஆக்கினையைத் திருப்பமாட்டேன்; அவர்கள் சகோதரன் உடன்படிக்கையை நினையாமல், சிறைப்பட்டவர்களை முழுதும் ஏதோமியர் கையில் ஒப்பித்தார்களே.", "en": "Thus saith the LORD ; For three transgressions of Tyrus, and for four, I will not turn away the punishment thereof; because they delivered up the whole captivity to Edom, and remembered not the brotherly covenant:"}, {"verse": 10, "start": 135.7, "end": 143.91, "ta": "தீருவின் மதிலுக்குள் தீக்கொளுத்துவேன்; அது அதின் அரமனைகளைப் பட்சிக்கும் என்று கர்த்தர் சொல்லுகிறார்.", "en": "But I will send a fire on the wall of Tyrus, which shall devour the palaces thereof."}, {"verse": 11, "start": 143.91, "end": 165.78, "ta": "மேலும்: ஏதோமுடைய மூன்று பாதகங்களினிமித்தமும், நாலு பாதகங்களினிமித்தமும், நான் அவன் ஆக்கினையைத் திருப்பமாட்டேன்; அவன் தன் சகோதரனைப் பட்டயத்தோடே தொடர்ந்து, தன் மனதை இரக்கமற்றதாக்கி, தன் கோபத்தினாலே என்றைக்கும் அவனைப் பீறிப்போட்டு, தன் மூர்க்கத்தை நித்தியகாலமாக வைத்திருக்கிறானே.", "en": "Thus saith the LORD ; For three transgressions of Edom, and for four, I will not turn away the punishment thereof; because he did pursue his brother with the sword, and did cast off all pity, and his anger did tear perpetually, and he kept his wrath for ever:"}, {"verse": 12, "start": 165.78, "end": 173.42, "ta": "தேமானிலே: தீக்கொளுத்துவேன்; அது போஸ்றாவின் அரமனைகளைப் பட்சிக்கும் என் கர்த்தர் சொல்லுகிறார்.", "en": "But I will send a fire upon Teman, which shall devour the palaces of Bozrah."}, {"verse": 13, "start": 173.42, "end": 192.64, "ta": "கர்த்தர் சொல்லுகிறது என்னவன்றால்: அம்மோன் புத்திரரின் மூன்று பாதகங்களினிமித்தமும் நாலு பாதகங்களினிமித்தமும் நான் அவர்கள் ஆக்கினையைத் திருப்பமாட்டேன்; அவர்கள் தங்கள் எல்லைகளை விஸ்தாரமாக்கும்படிக்குக் கீலேயாத் தேசத்தின் கர்ப்பஸ்திரீகளைக் கீறிப்போட்டார்களே.", "en": "Thus saith the LORD ; For three transgressions of the children of Ammon, and for four, I will not turn away the punishment thereof; because they have ripped up the women with child of Gilead, that they might enlarge their border:"}, {"verse": 14, "start": 192.64, "end": 202.93, "ta": "ரப்பாவின் மதிலுக்குள் தீக்கொளுத்துவேன்; அது யுத்தநாளின் முழக்கமாகவும், பெருங்காற்றின் புசலாகவும் அதின் அரமனைகளைப் பட்சிக்கும்.", "en": "But I will kindle a fire in the wall of Rabbah, and it shall devour the palaces thereof, with shouting in the day of battle, with a tempest in the day of the whirlwind:"}, {"verse": 15, "start": 202.93, "end": 210.36, "ta": "அவர்களுடைய ராஜாவும், அவனுடைய அதிபதிகளும் சிறைப்பட்டுப்போவார்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And their king shall go into captivity, he and his princes together, saith the LORD ."}]}, "2": {"chapter": 2, "duration": 204.17, "audio_url": "audio_ot/OT30_02.mp3", "total_verses": 16, "verses": [{"verse": 1, "start": 3.8, "end": 19.35, "ta": "கர்த்தர் சொல்லுகிறது என்னவென்றால்: மோவாபின் மூன்று பாதகங்களினிமித்தமும், நாலு பாதகங்களினிமித்தமும், நான் அவன் ஆக்கினையைத் திருப்பமாட்டேன்; அவன் ஏதோமுடைய ராஜாவின் எலும்புகளை நீறாகச் சுட்டுப்போட்டானே.", "en": "Thus saith the LORD ; For three transgressions of Moab, and for four, I will not turn away the punishment thereof; because he burned the bones of the king of Edom into lime:"}, {"verse": 2, "start": 19.35, "end": 30.99, "ta": "மோவாப்தேசத்தில் தீக்கொளுத்துவேன்; அது கீரியாத்தின் அரமனைகளைப் பட்சிக்கும்; மோவாபியர் அமளியோடும் ஆர்ப்பரிப்போடும் எக்காள சத்தத்தோடும் சாவார்கள்.", "en": "But I will send a fire upon Moab, and it shall devour the palaces of Kerioth: and Moab shall die with tumult, with shouting, and with the sound of the trumpet:"}, {"verse": 3, "start": 30.99, "end": 41.93, "ta": "நியாயாதிபதியை அவர்கள் நடுவில் இராதபடிக்கு நான் சங்காரம்பண்ணி, அவனோடே அவர்களுடைய பிரபுக்களையெல்லாம் கொன்றுபோடுவேன் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And I will cut off the judge from the midst thereof, and will slay all the princes thereof with him, saith the LORD ."}, {"verse": 4, "start": 41.93, "end": 60.53, "ta": "மேலும்: யூதாவின் மூன்று பாதகங்களினிமித்தமும் நாலு பாதகங்களினிமித்தமும் நான் அவர்கள் ஆக்கினையைத் திருப்பமாட்டேன்; அவர்கள் கர்த்தருடைய வேதத்தை வெறுத்து, அவருடைய கட்டளைகளைக் கைக்கொள்ளாமல், தங்கள் பிதாக்கள் பின்பற்றின பொய்களினால் மோசம்போனார்களே.", "en": "Thus saith the LORD ; For three transgressions of Judah, and for four, I will not turn away the punishment thereof; because they have despised the law of the LORD , and have not kept his commandments, and their lies caused them to err, after the which their fathers have walked:"}, {"verse": 5, "start": 60.53, "end": 68.55, "ta": "யூதாவிலே நான் தீக்கொளுத்துவேன்; அது எருசலேமின் அரமனைகளைப் பட்சிக்கும் என்று கர்த்தர் சொல்லுகிறார்.", "en": "But I will send a fire upon Judah, and it shall devour the palaces of Jerusalem."}, {"verse": 6, "start": 68.55, "end": 84.6, "ta": "மேலும்: இஸ்ரவேலின் மூன்று பாதகங்களினிமித்தமும், நாலு பாதகங்களினிமித்தமும், நான் அவர்களுடைய ஆக்கினையைத் திருப்பமாட்டேன், அவர்கள் நீதிமானைப் பணத்துக்கும், எளியவனை ஒரு ஜோடு பாதரட்சைக்கும் விற்றுப்போட்டார்களே.", "en": "Thus saith the LORD ; For three transgressions of Israel, and for four, I will not turn away the punishment thereof; because they sold the righteous for silver, and the poor for a pair of shoes;"}, {"verse": 7, "start": 84.6, "end": 99.86, "ta": "அவர்கள் தரித்திரருடைய தலையின்மேல் மண்ணைவாரி இறைத்து, சிறுமையானவர்களின் வழியைப் புரட்டுகிறார்கள்; என் பரிசுத்த நாமத்தைக் குலைச்சலாக்கும்படிக்கு மகனும் தகப்பனும் ஒரு பெண்ணிடத்தில் பிரவேசிக்கிறார்கள்.", "en": "That pant after the dust of the earth on the head of the poor, and turn aside the way of the meek: and a man and his father will go in unto the same maid, to profane my holy name:"}, {"verse": 8, "start": 99.86, "end": 114.7, "ta": "அவர்கள் சகல பீடங்களருகிலும் அடைமானமாய் வாங்கின வஸ்திரங்களின்மேல் படுத்துக்கொண்டு, தெண்டம் பிடிக்கப்பட்டவர்களுடைய மதுபானத்தைத் தங்கள் தேவர்களின் கோவிலிலே குடிக்கிறார்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And they lay themselves down upon clothes laid to pledge by every altar, and they drink the wine of the condemned in the house of their god."}, {"verse": 9, "start": 114.7, "end": 129.19, "ta": "நானோ: கேதுருமரங்களைப்போல் உயரமும், கர்வாலி மரங்களைப்போல் வைரமுமாயிருந்த எமோரியனை அவர்களுக்கு முன்பாக அழித்தேன்; உயர இருந்த அவனுடைய கனியையும், தாழ இருந்த அவனுடைய வேர்களையும் அழித்துப்போட்டு,", "en": "Yet destroyed I the Amorite before them, whose height was like the height of the cedars, and he was strong as the oaks; yet I destroyed his fruit from above, and his roots from beneath."}, {"verse": 10, "start": 129.19, "end": 139.98, "ta": "நீங்கள் எமோரியனுடைய தேசத்தைக் கட்டிக்கொள்ளும்படிக்கு உங்களை நான் எகிப்துதேசத்திலிருந்து வரப்பண்ணி, உங்களை நாற்பது வருஷமாக வனாந்தரத்திலே வழிநடத்தி,", "en": "Also I brought you up from the land of Egypt, and led you forty years through the wilderness, to possess the land of the Amorite."}, {"verse": 11, "start": 139.98, "end": 153.54, "ta": "உங்கள் குமாரரில் சிலரைத் தீர்க்கதரிசிகளாகவும் உங்கள் வாலிபரில் சிலரை நசரேயராகவும் எழும்பப்பண்ணினேன்; இஸ்ரவேல் புத்திரரே, இப்படி நான் செய்யவில்லையா என்று கர்த்தர் கேட்கிறார்.", "en": "And I raised up of your sons for prophets, and of your young men for Nazarites. Is it not even thus, O ye children of Israel? saith the LORD ."}, {"verse": 12, "start": 153.54, "end": 163.98, "ta": "நீங்களோ நசரேயருக்குத் திராட்சரசம் குடிக்கக் கொடுத்து, தீர்க்கதரிசிகளை நோக்கி: நீங்கள் தீர்க்கதரிசனஞ்சொல்லவேண்டாம் என்று கற்பித்தீர்கள்.", "en": "But ye gave the Nazarites wine to drink; and commanded the prophets, saying, Prophesy not."}, {"verse": 13, "start": 163.98, "end": 173.77, "ta": "இதோ, கோதுமைக்கட்டுகள் நிறைபாரமாக ஏற்றப்பட்ட வண்டியில் இருத்துகிறதுபோல, நான் உங்களை நீங்கள் இருக்கிற ஸ்தலத்தில் இருத்துவேன்.", "en": "Behold, I am pressed under you, as a cart is pressed that is full of sheaves."}, {"verse": 14, "start": 173.77, "end": 184.42, "ta": "அப்பொழுது வேகமானவன் ஓடியும் புகலிடமில்லை; பலவான் தன் பலத்தினால் பலப்படுவதுமில்லை; பராக்கிரமசாலி தன் பிராணனைத் தப்புவிப்பதுமில்லை.", "en": "Therefore the flight shall perish from the swift, and the strong shall not strengthen his force, neither shall the mighty deliver himself:"}, {"verse": 15, "start": 184.42, "end": 195.57, "ta": "வில்லைப் பிடிக்கிறவன் நிற்பதுமில்லை; வேகமானன் தன் கால்களால் தப்பிப்போவதுமில்லை; குதிரையின் மேல் ஏறுகிறவன் தன் பிராணனை இரட்சிப்பதுமில்லை.", "en": "Neither shall he stand that handleth the bow; and he that is swift of foot shall not deliver himself: neither shall he that rideth the horse deliver himself."}, {"verse": 16, "start": 195.57, "end": 202.67, "ta": "பலசாலிகளுக்குள்ளே தைரியவான் அந்நாளிலே நிர்வாணியாய் ஓடிப்போவான் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And he that is courageous among the mighty shall flee away naked in that day, saith the LORD ."}]}, "3": {"chapter": 3, "duration": 171.88, "audio_url": "audio_ot/OT30_03.mp3", "total_verses": 15, "verses": [{"verse": 1, "start": 3.8, "end": 14.52, "ta": "இஸ்ரவேல் புத்திரரே, கர்த்தராகிய நான் எகிப்துதேசத்திலிருந்து வரப்பண்ணின முழுக்குடும்பமாகிய உங்களுக்கு விரோதமாய்ச் சொல்லிய இந்த வசனத்தைக் கேளுங்கள்.", "en": "Hear this word that the LORD hath spoken against you, O children of Israel, against the whole family which I brought up from the land of Egypt, saying,"}, {"verse": 2, "start": 14.52, "end": 24.89, "ta": "பூமியின் எல்லா வம்சங்களுக்குள்ளும் உங்களை மாத்திரம் அறிந்துகொண்டேன்; ஆகையால் உங்களுடைய எல்லா அக்கிரமங்களினிமித்தமும் உங்களைத் தண்டிப்பேன்.", "en": "You only have I known of all the families of the earth: therefore I will punish you for all your iniquities."}, {"verse": 3, "start": 24.89, "end": 29.64, "ta": "இரண்டுபேர் ஒருமனப்பட்டிருந்தாலொழிய ஒருமித்து நடந்துபோவார்களோ?", "en": "Can two walk together, except they be agreed?"}, {"verse": 4, "start": 29.64, "end": 39.41, "ta": "தனக்கு இரை அகப்படாமலிருக்கக் காட்டிலே சிங்கம் கெர்ச்சிக்குமோ? இரை அகப்படாமலிருக்கும் பாலசிங்கம் தன் கெபியிலிருந்து சத்தமிடுமோ?", "en": "Will a lion roar in the forest, when he hath no prey? will a young lion cry out of his den, if he have taken nothing?"}, {"verse": 5, "start": 39.41, "end": 50.19, "ta": "குருவிக்குத் தரையிலே சுருக்குப்போடப்படாதிருந்தால், அது கண்ணியில் அகப்படுமோ? ஒன்றும் படாதிருக்கையில், கண்ணி தரையிலிருந்து எடுக்கப்படுமோ?", "en": "Can a bird fall in a snare upon the earth, where no gin is for him? shall one take up a snare from the earth, and have taken nothing at all?"}, {"verse": 6, "start": 50.19, "end": 58.33, "ta": "ஊரில் எக்காளம் ஊதினால் ஜனங்கள் கலங்காதிருப்பார்களோ? கர்த்தருடைய செயல் இல்லாமல் ஊரில் தீங்கு உண்டாகுமோ?", "en": "Shall a trumpet be blown in the city, and the people not be afraid? shall there be evil in a city, and the LORD hath not done it ? …: or, shall not the LORD do somewhat?"}, {"verse": 7, "start": 58.33, "end": 67.49, "ta": "கர்த்தராகிய ஆண்டவர் தீர்க்கதரிசிகளாகிய தம்முடைய ஊழியக்காரருக்குத் தமது இரகசியத்தை வெளிப்படுத்தாமல் ஒரு காரியத்தையும் செய்யார்.", "en": "Surely the Lord GOD will do nothing, but he revealeth his secret unto his servants the prophets."}, {"verse": 8, "start": 67.49, "end": 77.12, "ta": "சிங்கம் கெர்ச்சிக்கிறது, யார் பயப்படாதிருப்பான்? கர்த்தராகிய ஆண்டவர் பேசுகிறார், யார் தீர்க்கதரிசனம் சொல்லாதிருப்பான்?", "en": "The lion hath roared, who will not fear? the Lord GOD hath spoken, who can but prophesy?"}, {"verse": 9, "start": 77.12, "end": 92.38, "ta": "நாங்கள் சமாரியாவின் பர்வதங்களில வந்து கூடி, அதின் நடுவில் நடக்கிற பெரிய கலகங்களையும் அதற்குள் செய்யப்படுகிற இடுக்கண்களையும் பாருங்கள் என்று அஸ்தோத்தின் அரமனைகள்மேலும், எகிப்துதேசத்தின் அரமனைகள்மேலும் கூறுங்கள்.", "en": "Publish in the palaces at Ashdod, and in the palaces in the land of Egypt, and say, Assemble yourselves upon the mountains of Samaria, and behold the great tumults in the midst thereof, and the oppressed in the midst thereof."}, {"verse": 10, "start": 92.38, "end": 102.42, "ta": "அவர்கள் செம்மையானதைச் செய்ய அறியாமல், தங்கள் அரமனைகளில் கொடுமையையும் கொள்ளையையும் குவித்துக்கொள்ளுகிறார்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "For they know not to do right, saith the LORD , who store up violence and robbery in their palaces."}, {"verse": 11, "start": 102.42, "end": 115.51, "ta": "ஆகையால் சத்துரு வந்து, தேசத்தைச் சூழ்ந்துகொண்டு உன்பெலத்தை உன்னிலிருந்து அற்றுப்போகப்பண்ணுவான்; அப்பொழுது உன் அரமனைகள் கொள்ளையிடப்படும் என்று கர்த்தராகிய ஆண்டவர் சொல்லுகிறார்.", "en": "Therefore thus saith the Lord GOD ; An adversary there shall be even round about the land; and he shall bring down thy strength from thee, and thy palaces shall be spoiled."}, {"verse": 12, "start": 115.51, "end": 135.52, "ta": "மேலும்: ஒரு மேய்ப்பன் இரண்டு கால்களையாவது ஒரு காதின் துண்டையாவது சிங்கத்தின் வாயிலிருந்து பிடுங்கித் தப்புவிக்குமாப்போல, சமாரியாவில் குடியிருக்கிற இஸ்ரவேல் புத்திரர் ஒரு படுக்கையின் மூலையிலிருந்தும், ஒரு மஞ்சத்தின்மேலிருந்தும் தப்புவிக்கப்படுவார்களென்று, கர்த்தர் சொல்லுகிறார்.", "en": "Thus saith the LORD ; As the shepherd taketh out of the mouth of the lion two legs, or a piece of an ear; so shall the children of Israel be taken out that dwell in Samaria in the corner of a bed, and in Damascus in a couch."}, {"verse": 13, "start": 135.52, "end": 145.89, "ta": "ஆகையால் நீங்கள் கேட்டு யாக்கோபு வம்சத்தாருக்குள்ளே சாட்சியாக அறிவிக்கவேண்டியது: சேனைகளின் தேவனாயிருக்கிற கர்த்தராகிய ஆண்டவர் சொல்லுகிறது என்னவென்றால்,", "en": "Hear ye, and testify in the house of Jacob, saith the Lord GOD , the God of hosts,"}, {"verse": 14, "start": 145.89, "end": 157.15, "ta": "நான் இஸ்ரவேலுடைய பாதகங்களினிமித்தம் அவனை விசாரிக்கும்நாளிலே நான் பெத்தேலின் பலிபீடங்களை விசாரிப்பேன்; பலிபீடத்தின் கொம்புகள் வெட்டுண்டு தரையிலே விழும்.", "en": "That in the day that I shall visit the transgressions of Israel upon him I will also visit the altars of Beth-el: and the horns of the altar shall be cut off, and fall to the ground."}, {"verse": 15, "start": 157.15, "end": 170.38, "ta": "மாரிகாலத்Ġρ வீட்டையும் கோடைகாலத்து வீட்டையும் அழοப்பேன்; அப்பொழுது யானைத்தந்தத்தால் செய்யப்பட்ட வீடுகள் அழியும்; பெரிய வீடுகளுக்கும் முடிவு வரும் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And I will smite the winter house with the summer house; and the houses of ivory shall perish, and the great houses shall have an end, saith the LORD ."}]}, "4": {"chapter": 4, "duration": 204.51, "audio_url": "audio_ot/OT30_04.mp3", "total_verses": 13, "verses": [{"verse": 1, "start": 3.8, "end": 19.59, "ta": "சமாரியாவின் மலைகளிலுள்ள பாசானின் மாடுகளே, நீங்கள் இந்த வார்த்தைகளைக் கேளுங்கள்; தரித்திரரை ஒடுக்கி, எளியவர்களை நொறுக்கி, அவர்களுடைய எஜமான்களை நோக்கி: நாங்கள் குடிக்கும்படிக் கொண்டுவாருங்கள் என்று சொல்லுகிறீர்கள்.", "en": "Hear this word, ye kine of Bashan, that are in the mountain of Samaria, which oppress the poor, which crush the needy, which say to their masters, Bring, and let us drink."}, {"verse": 2, "start": 19.59, "end": 32.97, "ta": "இதோ, கர்த்தராகிய ஆண்டவர் உங்களைத் துறடுகளாலும், உங்கள் பின்சந்ததியை மீன்பிடிக்கிற தூண்டில்களாலும் இழுத்துக்கொண்டுபோகும் நாட்கள் வருமென்று அவர் தம்முடைய பரிசுத்தத்தைக்கொண்டு ஆணையிட்டார்.", "en": "The Lord GOD hath sworn by his holiness, that, lo, the days shall come upon you, that he will take you away with hooks, and your posterity with fishhooks."}, {"verse": 3, "start": 32.97, "end": 44.74, "ta": "அப்பொழுது நீங்கள் ஒவ்வொருவனும் அரமனைக்குச் சுமந்துகொண்டுபோவதை எறிந்துவிட்டு, தனக்கு எதிரான திறப்புகளின் வழியாய்ப் புறப்பட்டுப்போவீர்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And ye shall go out at the breaches, every cow at that which is before her; and ye shall cast them into the palace, saith the LORD ."}, {"verse": 4, "start": 44.74, "end": 56.71, "ta": "பெத்தேலுக்குப் போய்த் துரோகம் பண்ணுங்கள், கில்காலுக்குப்போய்த் துரோகத்தைப் பெருகப்பண்ணி, காலைதோறும் உங்கள் பலிகளையும் மூன்றாம் வருஷத்திலே உங்கள் தசமபாகங்களையும் செலுத்தி,", "en": "Come to Beth-el, and transgress; at Gilgal multiply transgression; and bring your sacrifices every morning, and your tithes after three years:"}, {"verse": 5, "start": 56.71, "end": 70.56, "ta": "புளித்தமாவுள்ள ஸ்தோத்திரபலியோடே தூபங்காட்டி, உற்சாக பலிகளைக் கூறித் தெரியப்படுத்துங்கள்; இஸ்ரவேல் புத்திரரே, இப்படிச் செய்வதே உங்களுக்குப் பிரியம் என்று கர்த்தராகிய ஆண்டவர் சொல்லுகிறார்.", "en": "And offer a sacrifice of thanksgiving with leaven, and proclaim and publish the free offerings: for this liketh you, O ye children of Israel, saith the Lord GOD ."}, {"verse": 6, "start": 70.56, "end": 85.81, "ta": "ஆகையால் நான் உங்கள் பட்டணங்களில் எல்லாம் உங்கள் பல்லுகளுக்கு ஓய்வையும், உங்கள் ஸ்தலங்களில் எல்லாம் அப்பக்குறைவையும் கட்டளையிட்டேன்; ஆகிலும் நீங்களே என்னிடத்தில் திரும்பாமற்போனீர்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And I also have given you cleanness of teeth in all your cities, and want of bread in all your places: yet have ye not returned unto me, saith the LORD ."}, {"verse": 7, "start": 85.81, "end": 103.34, "ta": "இதுவுமல்லாமல் அறுப்புக்காலம் வர இன்னும் மூன்றுமாதம் இருக்கும்போதே மழையை நான் தடுத்தேன், ஒரு பட்டணத்தின்மேல் மழைபெய்யவும் ஒரு பட்டணத்தின்மேல் மழை பெய்யாமலிருக்கவும் பண்ணினேன்; ஒரு வயலின்மேல் மழைபெய்தது, மழைபெய்யாத மற்ற வயல் காய்ந்து போயிற்று.", "en": "And also I have withholden the rain from you, when there were yet three months to the harvest: and I caused it to rain upon one city, and caused it not to rain upon another city: one piece was rained upon, and the piece whereupon it rained not withered."}, {"verse": 8, "start": 103.34, "end": 116.72, "ta": "இரண்டு மூன்று பட்டணங்களின் மனுஷர் தண்ண ΰ் குடிக்க பட்டணத்துக்குப் போய் அலைந்தும் தாகந்தீத்துக்கொள்ளவில்லை; ஆகிலும் நீங்கள் என்னிடத்தில் திரும்பாமற்போனீர்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "So two or three cities wandered unto one city, to drink water; but they were not satisfied: yet have ye not returned unto me, saith the LORD ."}, {"verse": 9, "start": 116.72, "end": 134.38, "ta": "கருக்காயினாலும் விஷப்பனியினாலும் உங்களை தண்டித்தேன்; உங்கள் சோலைகளிலும் திராட்சத்தோட்டங்களிலும் அத்திமரங்களிலும் ஒலிவமரங்களிலும் மிகுதியானதைப் பச்சைப்புழு அரித்துப்போட்டது; ஆகிலும் என்னிடத்தில் திரும்பாமற்போனார்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "I have smitten you with blasting and mildew: when your gardens and your vineyards and your fig trees and your olive trees increased, the palmerworm devoured them: yet have ye not returned unto me, saith the LORD ."}, {"verse": 10, "start": 134.38, "end": 155.45, "ta": "எகிப்தில் உண்டானதற்கு ஒத்த கொள்ளைநோயை உங்களுக்குள் அனுப்பினேன்; உங்கள் வாலிபரைப் பட்டயத்தாலே கொன்றேன்; உங்கள் குதிரைகளை அழித்துப்போட்டேன்; உங்கள் பாளயங்களின் நாற்றத்தை உங்கள் நாசிகளிலும் ஏற்றப்பண்ணினேன்; ஆகிலும் நீங்கள் என்னிடத்தில் திரும்பாமற்போனீர்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "I have sent among you the pestilence after the manner of Egypt: your young men have I slain with the sword, and have taken away your horses; and I have made the stink of your camps to come up unto your nostrils: yet have ye not returned unto me, saith the LORD ."}, {"verse": 11, "start": 155.45, "end": 172.17, "ta": "சோதோமையும் கொமோராவையும் தேவன் கவிழ்த்துப்போட்டதுபோல, உங்களைக் கவிழ்த்துப்போட்டேன்; நீங்கள் அக்கினியினின்று பறிக்கப்பட்ட கொள்ளியைப்போல இருந்தீர்கள்; ஆனாலும் நீங்கள் என்னிடத்தில் திரும்பாமற்போனீர்கள் என்று கர்த்தர் சொல்லுகிறார்.", "en": "I have overthrown some of you, as God overthrew Sodom and Gomorrah, and ye were as a firebrand plucked out of the burning: yet have ye not returned unto me, saith the LORD ."}, {"verse": 12, "start": 172.17, "end": 183.14, "ta": "ஆகையால் இஸ்ரவேலே, இந்தப்பிரகாரமாக உனக்குச் செய்வேன்; இஸ்ரவேலே, நான் இப்படி உனக்குச்செய்யப்போகிறபடியினால் உன் தேவனைச் சந்திக்கும்படி ஆயத்தப்படு.", "en": "Therefore thus will I do unto thee, O Israel: and because I will do this unto thee, prepare to meet thy God, O Israel."}, {"verse": 13, "start": 183.14, "end": 203.01, "ta": "அவர் பர்வதங்களை உருவாக்கினவரும் காற்றைச் சிருஷ்டித்தவரும், மனுஷனுடைய நினைவுகள் இன்னதென்று அவனுக்கு வெளிப்படுத்துகிறவரும், விடியற்காலத்தை அந்தகாரமாக்குகிறவரும், பூமியினுடைய உயர்ந்த ஸ்தானங்களின்மேல் உலாவுகிறவருமாயிருக்கிறார்; சேனைகளின் தேவனாகிய கர்த்தர் என்பது அவருடைய நாமம்.", "en": "For, lo, he that formeth the mountains, and createth the wind, and declareth unto man what is his thought, that maketh the morning darkness, and treadeth upon the high places of the earth, The LORD , The God of hosts, is his name."}]}, "5": {"chapter": 5, "duration": 298.24, "audio_url": "audio_ot/OT30_05.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 10.83, "ta": "இஸ்ரவேல் வம்சத்தாரே, உங்களைக்குறித்து நான் புலம்பிச் சொல்லும் இந்த வசனத்தைக் கேளுங்கள்.", "en": "Hear ye this word which I take up against you, even a lamentation, O house of Israel."}, {"verse": 2, "start": 10.83, "end": 21.69, "ta": "இஸ்ரவேல் என்னும் கன்னிகை விழுந்தாள், அவள் இனி ஒருபோதும் எழுந்திருக்கமாட்டாள்; தன் தேசத்தில் விழுந்துகிடக்கிறாள், அவளை எடுப்பாரில்லை.", "en": "The virgin of Israel is fallen; she shall no more rise: she is forsaken upon her land; there is none to raise her up."}, {"verse": 3, "start": 21.69, "end": 33.55, "ta": "நகரத்திலிருந்து புறப்பட்ட ஆயிரம்பேரில் நூறுபேரும், நூறுபேரில் பத்துப்பேரும் இஸ்ரவேல் வம்சத்தாருக்கு மீந்திருப்பார்கள் என்று கர்த்தராகிய தேவன் சொல்லுகிறார்.", "en": "For thus saith the Lord GOD ; The city that went out by a thousand shall leave an hundred, and that which went forth by an hundred shall leave ten, to the house of Israel."}, {"verse": 4, "start": 33.55, "end": 41.71, "ta": "கர்த்தர் இஸ்ரவேல் வம்சத்தாருக்குச் சொல்லுகிறது என்னவென்றால் என்னைத் தேடுங்கள், அப்பொழுது பிழைப்பீர்கள்.", "en": "For thus saith the LORD unto the house of Israel, Seek ye me, and ye shall live:"}, {"verse": 5, "start": 41.71, "end": 54.07, "ta": "பெத்தேலைத் தேடாதேயுங்கள், கில்காலிலும் சேராதேயுங்கள், பெயெர்செபாவுக்கும் போகாதேயுங்கள்; கில்கால் கிறையிருப்பாகவும், பெத்தேல் பாழான ஸ்தலமாகவும் போகும்.", "en": "But seek not Beth-el, nor enter into Gilgal, and pass not to Beer-sheba: for Gilgal shall surely go into captivity, and Beth-el shall come to nought."}, {"verse": 6, "start": 54.07, "end": 66.63, "ta": "கர்த்தரைத் தேடுங்கள், அப்பொழுது பிழைப்பீர்கள்; இல்லாவிட்டால் பெத்தேலில் இருக்கிற ஒருவராலும் அறிவிக்கப்படாத அக்கினி யோசேப்பின் வீட்டில் பற்றி அதைப் பட்சிக்கும்.", "en": "Seek the LORD , and ye shall live; lest he break out like fire in the house of Joseph, and devour it , and there be none to quench it in Beth-el."}, {"verse": 7, "start": 66.63, "end": 73.52, "ta": "நியாயத்தை எட்டியாக மாற்றி, நீதியைத் தரையிலே விழப்பண்ணுகிறவர்களே, அவரைத் தேடுங்கள்.", "en": "Ye who turn judgment to wormwood, and leave off righteousness in the earth,"}, {"verse": 8, "start": 73.52, "end": 93.26, "ta": "அவர் அறுமீனையும் மிருகசீரிஷத்தையும் உண்டாக்கினவர்; அவர் மரண இருளை விடியற்காலமாக மாற்றி பகலை இராத்திரியாக அந்தகாரப்படுத்துகிறார்; அவர் சமுத்திரத்தின் தண்ணீர்களை வரவழைத்து, அவைகளைப் பூமியின் விசாலத்தின்மேல் ஏற்றுகிறவர்; கர்த்தர் என்பது அவருடைய நாமம்.", "en": "Seek him that maketh the seven stars and Orion, and turneth the shadow of death into the morning, and maketh the day dark with night: that calleth for the waters of the sea, and poureth them out upon the face of the earth: The LORD is his name:"}, {"verse": 9, "start": 93.26, "end": 102.42, "ta": "அரணான ஸ்தலத்தின்மேல் பாழ்க்கடிப்பு வரத்தக்கதாக, அவர் கொள்ளை கொடுத்தவனைப் பலத்தவனுக்கு விரோதமாய் லகுவடையப்பண்ணுகிறவர்.", "en": "That strengtheneth the spoiled against the strong, so that the spoiled shall come against the fortress."}, {"verse": 10, "start": 102.42, "end": 109.87, "ta": "ஒலிமுகவாசலிலே கடிந்துகொள்ளுகிறவனை அவர்கள் பகைத்து, யதார்த்தமாய்ப் பேசுகிறவனை வெறுக்கிறார்கள்.", "en": "They hate him that rebuketh in the gate, and they abhor him that speaketh uprightly."}, {"verse": 11, "start": 109.87, "end": 131.1, "ta": "நீங்கள் தரித்திரனை மிதித்து, அவன் கையிலே தானியத்தைச் சுமைமையாய் வாங்குகிறபடியினால், நீங்கள் பொளிந்த கற்களால் வீடுகளைக்கட்டினீர்கள். ஆனாலும் அவைகளில் நீங்கள் குடியிருப்பதில்லை; இன்பமான திராட்சத்தோட்டங்களை நாட்டினீர்கள், ஆனாலும் அவைகளின் இரசத்தை நீங்கள் குடிப்பதில்லை.", "en": "Forasmuch therefore as your treading is upon the poor, and ye take from him burdens of wheat: ye have built houses of hewn stone, but ye shall not dwell in them; ye have planted pleasant vineyards, but ye shall not drink wine of them."}, {"verse": 12, "start": 131.1, "end": 143.88, "ta": "உங்கள் மீறுதல்கள் மிகுதியென்றும், உங்கள் பாவங்கள் பலத்ததென்றும் அறிவேன்; நீதிமானை ஒடுக்கி, பரிதானம் வாங்கி ஒலிமுகவாசலில் ஏழைகளின் நியாயத்தைப் புரட்டுகிறீர்கள்.", "en": "For I know your manifold transgressions and your mighty sins: they afflict the just, they take a bribe, and they turn aside the poor in the gate from their right ."}, {"verse": 13, "start": 143.88, "end": 151.05, "ta": "ஆகையால் புத்திமான் அந்தக் காலத்திலே மெளனமாயிருக்கவேண்டும்; அந்தக் காலம் தீமையான காலம்.", "en": "Therefore the prudent shall keep silence in that time; for it is an evil time."}, {"verse": 14, "start": 151.05, "end": 162.41, "ta": "நீங்கள் பிழைக்கும்படிக்குத் தீமையை அல்ல, நன்மையைத் தேடுங்கள்; அப்பொழுது நீங்கள் சொல்லுகிறபடியே சேனைகளின் தேவனாகிய கர்த்தர் உங்களோடே இருப்பார்.", "en": "Seek good, and not evil, that ye may live: and so the LORD , the God of hosts, shall be with you, as ye have spoken."}, {"verse": 15, "start": 162.41, "end": 175.19, "ta": "நீங்கள் தீமையை வெறுத்து நன்மையை விரும்பி, ஒலிமுகவாசலில் நியாயத்தை நிலைப்படுத்துங்கள்; ஒருவேளை சேனைகளின் தேவனாகிய கர்த்தர் யோசேப்பிலே மீதியானவர்களுக்கு இரங்குவார்.", "en": "Hate the evil, and love the good, and establish judgment in the gate: it may be that the LORD God of hosts will be gracious unto the remnant of Joseph."}, {"verse": 16, "start": 175.19, "end": 195.99, "ta": "ஆதலால் ஆண்டவரும் சேனைகளின் தேவனுமாகிய கர்த்தர் சொல்லுகிறது என்னவென்றால்: எல்லாத்தெருக்களிலும் புலம்பல் உண்டாகும்; எல்லா வீதிகளிலும் ஐயோ! ஐயோ! என்று ஓலமிடுவார்கள்; பயிரிடுகிறவர்களைத் துக்கங்கொண்டாடுகிறதற்கும், ஒப்பாரி பாட அறிந்தவர்களைப் புலம்புகிறதற்கும் வரவழைப்பார்கள்.", "en": "Therefore the LORD , the God of hosts, the Lord, saith thus; Wailing shall be in all streets; and they shall say in all the highways, Alas! alas! and they shall call the husbandman to mourning, and such as are skilful of lamentation to wailing."}, {"verse": 17, "start": 195.99, "end": 204.94, "ta": "எல்லாத் திராட்சத்தோட்டங்களிலும் புலம்பல் உண்டாயிருக்கும், நான் உன் நடுவே கடந்துபோவேன் என்று கர்த்தர் சொல்லுகிறார்.", "en": "And in all vineyards shall be wailing: for I will pass through thee, saith the LORD ."}, {"verse": 18, "start": 204.94, "end": 215.38, "ta": "கர்த்தருடைய நாளை விரும்புகிறவர்களுக்கு ஐயோ! அதினால் உங்களுக்கு என்ன உண்டு? கர்த்தருடைய நாள் வெளிச்சமாயிராமல் அந்தகாரமாயிருக்கும்.", "en": "Woe unto you that desire the day of the LORD ! to what end is it for you? the day of the LORD is darkness, and not light."}, {"verse": 19, "start": 215.38, "end": 227.45, "ta": "சிங்கத்துக்குத் தப்பினவனுக்குக் கரடி எதிர்ப்பட்டதுபோலவும், அல்லது வீட்டுக்குள்ளே வந்து சுவரின்மேல் தன் கையை வைத்தபோது பாம்பு அவனைக் கடித்ததுபோலவும் இருக்கும்.", "en": "As if a man did flee from a lion, and a bear met him; or went into the house, and leaned his hand on the wall, and a serpent bit him."}, {"verse": 20, "start": 227.45, "end": 233.98, "ta": "கர்த்தருடைய நாள் வெளிச்சமாயிராமல், இருளும் பிரகாசமற்ற அந்தகாரமுமாயிருக்குமல்லவோ?", "en": "Shall not the day of the LORD be darkness, and not light? even very dark, and no brightness in it?"}, {"verse": 21, "start": 233.98, "end": 241.22, "ta": "உங்கள் பண்டிகைகளைப் பகைத்துவெறுக்கிறேன்; உங்கள் ஆசரிப்புநாட்களில் எனக்குப் பிரியமில்லை.", "en": "I hate, I despise your feast days, and I will not smell in your solemn assemblies."}, {"verse": 22, "start": 241.22, "end": 253.86, "ta": "உங்கள் தகனபலிகளையும் போஜனபலிகளையும் எனக்குப் படைத்தாலும் நான் அங்கீகரிக்கமாட்டேன்; கொழுமையான உங்கள் மிருகங்களின் ஸ்தோத்திரபலிகளையும் நான் நோக்கிப் பார்க்கமாட்டேன்.", "en": "Though ye offer me burnt offerings and your meat offerings, I will not accept them: neither will I regard the peace offerings of your fat beasts."}, {"verse": 23, "start": 253.86, "end": 260.89, "ta": "உன் பாட்டுகளின் இரைச்சலை என்னைவிட்டு அகற்று; உன் வீணைகளின் ஓசையை நான் கேட்கமாட்டேன்.", "en": "Take thou away from me the noise of thy songs; for I will not hear the melody of thy viols."}, {"verse": 24, "start": 260.89, "end": 266.71, "ta": "நியாயம் தண்ணீரைப்போலவும், நீதி வற்றாத நதியைப்போலவும் புரண்டுவரக்கடவது.", "en": "But let judgment run down as waters, and righteousness as a mighty stream."}, {"verse": 25, "start": 266.71, "end": 276.36, "ta": "இஸ்ரவேல் வம்சத்தாரே, நீங்கள் வனாந்தரத்திலே இருந்த நாற்பது வருஷம்வரையில் பலிகளையும் காணிக்கைகளையும் எனக்குச் செலுத்தினீர்களோ?", "en": "Have ye offered unto me sacrifices and offerings in the wilderness forty years, O house of Israel?"}, {"verse": 26, "start": 276.36, "end": 287.94, "ta": "நீங்கள் உங்களுக்கு உண்டாக்கின மோளேகுடைய கூடாரத்தையும், உங்கள் தேவர்களின் நட்சத்திர ராசியாகிய உங்கள் சொரூபங்களின் சப்பரத்தையும் சுமந்துகொண்டுவந்தீர்களே.", "en": "But ye have borne the tabernacle of your Moloch and Chiun your images, the star of your god, which ye made to yourselves."}, {"verse": 27, "start": 287.94, "end": 296.74, "ta": "ஆகையால் உங்களைத் தமஸ்குவுக்கு அப்பாலே குடியோட்டுவேன் என்று சேனைகளுடைய தேவன் என்னும் நாமமுள்ள கர்த்தர் சொல்லுகிறார்.", "en": "Therefore will I cause you to go into captivity beyond Damascus, saith the LORD , whose name is The God of hosts."}]}, "6": {"chapter": 6, "duration": 180.77, "audio_url": "audio_ot/OT30_06.mp3", "total_verses": 14, "verses": [{"verse": 1, "start": 3.8, "end": 16.52, "ta": "சீயோனிலே நிர்விசாரமாயிருக்கிறவர்களும் சமாரியாவின் பர்வதத்தை நம்பிக்கொண்டிருக்கிறவர்களும் ஜாதிகளின் தலைமையென்னப்பட்டு, இஸ்ரவேல் வம்சத்தார் தேடிவருகிறவர்களுமாகிய உங்களுக்கு ஐயோ!", "en": "Woe to them that are at ease in Zion, and trust in the mountain of Samaria, which are named chief of the nations, to whom the house of Israel came!"}, {"verse": 2, "start": 16.52, "end": 37.18, "ta": "நீங்கள் கல்னேமட்டும் சென்று, அவ்விடத்திலிருந்து ஆமாத் என்னும் பெரிய பட்டணத்துக்குப் போய், பெலிஸ்தருடைய காத் பட்டணத்துக்கு இறங்கி, அவைகள் இந்த ராஜ்யங்களைப்பார்க்கிலும் நல்லவைகளோ என்றும், அவைகளின் எல்லைகள் உங்கள் எல்லைகளைப்பார்க்கிலும் விஸ்தாரமானவைகளோ என்றும் பாருங்கள்.", "en": "Pass ye unto Calneh, and see; and from thence go ye to Hamath the great: then go down to Gath of the Philistines: be they better than these kingdoms? or their border greater than your border?"}, {"verse": 3, "start": 37.18, "end": 42.11, "ta": "தீங்குநாள் தூரமென்றெண்ணிக் கொடுமையின் ஆசனம் கிட்டிவரும்படி செய்து,", "en": "Ye that put far away the evil day, and cause the seat of violence to come near;"}, {"verse": 4, "start": 42.11, "end": 55.19, "ta": "தந்தக் கட்டில்களில் படுத்துக்கொண்டு, தங்கள் மஞ்சங்களின்மேல் சவுக்கியமாய்ச் சயனித்து, மந்தையிலுள்ள ஆட்டுக்குட்டிகளையும், மாட்டுத்தொழுவத்திலுள்ள கன்றுக்குட்டிகளையும் தின்று,", "en": "That lie upon beds of ivory, and stretch themselves upon their couches, and eat the lambs out of the flock, and the calves out of the midst of the stall;"}, {"verse": 5, "start": 55.19, "end": 61.19, "ta": "தம்புரை வாசித்துப் பாடி, தாவீதைப்போல் கீதவாத்தியங்களைத் தங்களுக்கு உண்டுபண்ணி,", "en": "That chant to the sound of the viol, and invent to themselves instruments of musick, like David;"}, {"verse": 6, "start": 61.19, "end": 73.63, "ta": "பெரிய பாத்திரங்களில் மதுபானத்தைக் குடித்து, சிறந்த பரிமளதைலங்களைப் பூசிக்கொள்ளுகிறார்கள்; ஆனாலும் யோசேப்புக்கு நேரிட்ட ஆபத்துக்குக் கவலைப்படாமற்போகிறார்கள்.", "en": "That drink wine in bowls, and anoint themselves with the chief ointments: but they are not grieved for the affliction of Joseph."}, {"verse": 7, "start": 73.63, "end": 84.71, "ta": "ஆகையால் அவர்கள் சிறையிருப்புக்குப் போகிறவர்களின் முன்னணியிலே போவார்கள்; இப்படியே செல்வமாய்ச் சயனித்தவர்களின் விருந்துகொண்டாடல் நின்றுபோகும்.", "en": "Therefore now shall they go captive with the first that go captive, and the banquet of them that stretched themselves shall be removed."}, {"verse": 8, "start": 84.71, "end": 103.01, "ta": "நான் யாக்கோபுடைய மேன்மையை வெறுத்து, அவனுடைய அரமனைகளைப் பகைக்கிறேன்; நான் நகரத்தையும் அதின் நிறைவையும் ஒப்புக்கொடுத்துவிடுவேன் என்று கர்த்தராகிய ஆண்டவர் தம்முடைய ஜீவனைக் கொண்டு ஆணையிட்டார் என்பதைச் சேனைகளின் தேவனாகிய கர்த்தர் சொல்லுகிறார்.", "en": "The Lord GOD hath sworn by himself, saith the LORD the God of hosts, I abhor the excellency of Jacob, and hate his palaces: therefore will I deliver up the city with all that is therein."}, {"verse": 9, "start": 103.01, "end": 108.65, "ta": "ஒரு வீட்டிலே பத்துப்பேர் மீதியாயிருந்தாலும் அவர்கள் செத்துப்போவார்கள்.", "en": "And it shall come to pass, if there remain ten men in one house, that they shall die."}, {"verse": 10, "start": 108.65, "end": 132.74, "ta": "அவர்களுடைய இனத்தானாவது, பிரேதத்தைத் தகிக்கிறவனாவது எலும்புகளை வீட்டிலிருந்துவெளியேகொண்டுபோகும்படிக்கு, அவைகளை எடுத்து வீட்டின் உட்புறத்திலே இருக்கிறவனை நோக்கி: உன்னிடத்தில் இன்னும் யாராயினும் உண்டோ என்று கேட்பான், அவன் இல்லையென்பான்; அப்பொழுது இவன்: நீ மெளனமாயிரு; கர்த்தருடைய நாமத்தைச் சொல்லலாகாது என்பான்.", "en": "And a man’s uncle shall take him up, and he that burneth him, to bring out the bones out of the house, and shall say unto him that is by the sides of the house, Is there yet any with thee? and he shall say, No. Then shall he say, Hold thy tongue: for we may not make mention of the name of the LORD ."}, {"verse": 11, "start": 132.74, "end": 141.89, "ta": "இதோ கர்த்தர் கட்டளையிட்டிருக்கிறார்; பெரிய வீட்டைத் திறப்புகள் உண்டாகவும், சிறிய வீடுகள் உண்டாகவும் அடிப்பார்.", "en": "For, behold, the LORD commandeth, and he will smite the great house with breaches, and the little house with clefts."}, {"verse": 12, "start": 141.89, "end": 153.47, "ta": "ஒரு கன்மலையின்மேல் குதிரைகள் ஓடுமோ? அங்கே ஒருவன் மாடுகளால் உழுவானோ? நியாயத்தை நஞ்சாகவும், நீதியின் கனியை எட்டியாகவும் மாற்றினீர்கள்.", "en": "Shall horses run upon the rock? will one plow there with oxen? for ye have turned judgment into gall, and the fruit of righteousness into hemlock:"}, {"verse": 13, "start": 153.47, "end": 162.54, "ta": "நாங்கள் எங்கள் பலத்தினாலே எங்களுக்குக் கொம்புகளை உண்டாக்கிக்கொள்ளவில்லையோ என்று சொல்லி வீண்காரியத்தில் மகிழுகிறார்கள்.", "en": "Ye which rejoice in a thing of nought, which say, Have we not taken to us horns by our own strength?"}, {"verse": 14, "start": 162.54, "end": 179.27, "ta": "இஸ்ரவேல் வம்சத்தாரே, இதோ நான் ஒரு ஜாதியை உங்களுக்கு விரோதமாக எழுப்புவேன்; அவர்கள் ஆமாத்துக்குள் பிரவேசிக்கிற வழிதொடங்கிச் சமனான நாட்டின் ஆறுமட்டாக உங்களை ஒடுக்குவார்கள் என்று சேனைகளின் தேவனாகிய கர்த்தர் சொல்லுகிறார்.", "en": "But, behold, I will raise up against you a nation, O house of Israel, saith the LORD the God of hosts; and they shall afflict you from the entering in of Hemath unto the river of the wilderness."}]}, "7": {"chapter": 7, "duration": 215.27, "audio_url": "audio_ot/OT30_07.mp3", "total_verses": 17, "verses": [{"verse": 1, "start": 3.8, "end": 16.84, "ta": "கர்த்தராகிய ஆண்டவர் எனக்குக் காண்பித்ததாவது: இதோ, ராஜாவினுடைய புல்லறுப்புக்குப்பின்பு இரண்டாம் கந்தாயத்துப் புல் முளைக்கத் தொடங்குகையில் அவர் வெட்டுக்கிளிகளை உண்டாக்கினார்.", "en": "Thus hath the Lord GOD shewed unto me; and, behold, he formed grasshoppers in the beginning of the shooting up of the latter growth; and, lo, it was the latter growth after the king’s mowings."}, {"verse": 2, "start": 16.84, "end": 29.96, "ta": "அவைகள் தேசத்தின் புல்லைத்தின்று தீர்ந்தபோது, நான்: கர்த்தராகிய ஆண்டவரே மன்னித்தருளும்; யாக்கோபு திரும்ப யாராலே எழுந்திருப்பான்? அவன் சிறுத்துப்போனான் என்றேன்.", "en": "And it came to pass, that when they had made an end of eating the grass of the land, then I said, O Lord GOD , forgive, I beseech thee: by whom shall Jacob arise? for he is small."}, {"verse": 3, "start": 29.96, "end": 34.78, "ta": "கர்த்தர் அதற்கு மனஸ்தாபப்பட்டு, அப்படி ஆவதில்லை என்றார்.", "en": "The LORD repented for this: It shall not be, saith the LORD ."}, {"verse": 4, "start": 34.78, "end": 49.66, "ta": "கர்த்தராகிய ஆண்டவர் எனக்குக் காண்பித்ததாவது: இதோ, அக்கினியாலே நியாயம் விசாரிப்பேன் என்று கர்த்தராகிய ஆண்டவர் ஏற்பட்டார்; அது மகா ஆழியைப் பட்சித்தது, அதில் ஒரு பங்கைப் பட்சித்துத் தீர்ந்தது.", "en": "Thus hath the Lord GOD shewed unto me: and, behold, the Lord GOD called to contend by fire, and it devoured the great deep, and did eat up a part."}, {"verse": 5, "start": 49.66, "end": 60.09, "ta": "அப்பொழுது நான்: கர்த்தராகிய ஆண்டவரே, நிறுத்துமே; யாக்கோபு திரும்ப யாராலே எழுந்திருப்பான்? அவன் சிறுத்துப்போனான் என்றேன்.", "en": "Then said I, O Lord GOD , cease, I beseech thee: by whom shall Jacob arise? for he is small."}, {"verse": 6, "start": 60.09, "end": 64.91, "ta": "கர்த்தர் அதற்கு மனஸ்தாபப்பட்டு, அப்படி ஆவதில்லை என்றார்.", "en": "The LORD repented for this: This also shall not be, saith the Lord GOD ."}, {"verse": 7, "start": 64.91, "end": 75.61, "ta": "பின்பு அவர் எனக்குக் காண்பித்ததாவது: இதோ தூக்குநூல் பிரமாணத்தினால் கட்டப்பட்ட ஒரு மதிலின்மேல் நின்றார்; அவர் கையில் தூக்குநூல் இருந்தது.", "en": "Thus he shewed me: and, behold, the Lord stood upon a wall made by a plumbline, with a plumbline in his hand."}, {"verse": 8, "start": 75.61, "end": 92.27, "ta": "கர்த்தர் என்னை நோக்கி: ஆமோசே, நீ என்னத்தைக் காண்கிறாய் என்றார்; தூக்நூலைக் காண்கிறேன் என்றேன்; அப்பொழுது ஆண்டவர்: இதோ, இஸ்ரவேலென்னும் என்ஜனத்தின் நடுவே தூக்குநூலை விடுவேன்; இனி அவர்களை மன்னிக்கமாட்டேன்.", "en": "And the LORD said unto me, Amos, what seest thou? And I said, A plumbline. Then said the Lord, Behold, I will set a plumbline in the midst of my people Israel: I will not again pass by them any more:"}, {"verse": 9, "start": 92.27, "end": 104.46, "ta": "ஈசாக்கின் மேடைகள் பாழும், இஸ்ரவேலின் பரிசுத்த ஸ்தலங்கள் அவாந்தரமுமாக்கப்படும்; நான் எரொபெயாம் வீட்டாருக்கு விரோதமாய்ப் பட்டயத்தோடே எழும்பிவருவேன் என்றார்.", "en": "And the high places of Isaac shall be desolate, and the sanctuaries of Israel shall be laid waste; and I will rise against the house of Jeroboam with the sword."}, {"verse": 10, "start": 104.46, "end": 120.13, "ta": "அப்பொழுது பெத்தேலில் ஆசாரியனான அத்சியா இஸ்ரவேலின் ராஜாவாகிய எரொபெயாமுக்கு அனுப்பி: ஆமோஸ் இஸ்ரவேல் வம்சத்தாரின் நடுவே உமக்கு விரோதமாகக் கட்டுப்பாடு பண்ணுகிறான்; தேசம் அவன் வார்த்தைகளையெல்லாம் சகிக்கமாட்டாது.", "en": "Then Amaziah the priest of Beth-el sent to Jeroboam king of Israel, saying, Amos hath conspired against thee in the midst of the house of Israel: the land is not able to bear all his words."}, {"verse": 11, "start": 120.13, "end": 131.61, "ta": "எரோபேயாம் பட்டயத்தினால் சாவான் என்றும், இஸ்ரவேல் தன்தேசத்திலிருந்து சிறைபிடித்துக்கொண்டுபோகப்படுவான் என்றும் ஆமோஸ் சொல்லுகிறான் என்று சொல்லச்சொன்னான்.", "en": "For thus Amos saith, Jeroboam shall die by the sword, and Israel shall surely be led away captive out of their own land."}, {"verse": 12, "start": 131.61, "end": 142.24, "ta": "அமத்சியா ஆமோசை நோக்கி: தரிசனம் பார்க்கிறவனே, போ; நீ யூதாதேசத்துக்கு ஓடிப்போ, அங்கே அப்பம் தின்று, அங்கே தீர்க்கதரிசனம் சொல்லு.", "en": "Also Amaziah said unto Amos, O thou seer, go, flee thee away into the land of Judah, and there eat bread, and prophesy there:"}, {"verse": 13, "start": 142.24, "end": 151.39, "ta": "பெத்தேலிலே இனித் தீர்க்கதரிசனம் சொல்லாதே; அது ராஜாவின் பரிசுத்த ஸ்தலமும் ராஜ்யத்தின் அரமனையுமாயிருக்கிறது என்றான்.", "en": "But prophesy not again any more at Beth-el: for it is the king’s chapel, and it is the king’s court."}, {"verse": 14, "start": 151.39, "end": 165.0, "ta": "ஆமோஸ் அமத்சியாவுக்குப் பிரதியுத்தரமாக: நான் தீர்க்கதரிசியுமல்ல, தீர்க்கதரிசியின் புத்திரனுமல்ல; நான் மந்தை மேய்க்கிறவனும், காட்டத்திப்பழங்களைப் பொறுக்குகிறவனுமாயிருந்தேன்.", "en": "Then answered Amos, and said to Amaziah, I was no prophet, neither was I a prophet’s son; but I was an herdman, and a gatherer of sycomore fruit:"}, {"verse": 15, "start": 165.0, "end": 176.62, "ta": "ஆனால் மந்தையின் பின்னாலே போகிறபோது என்னைக் கர்த்தர் அழைத்து, நீ போய் என் ஜனமாகிய இஸ்ரவேலுக்கு விரோதமாகத் தீர்க்கதரிசனம் சொல்லு என்று கர்த்தர் உரைத்தார்.", "en": "And the LORD took me as I followed the flock, and the LORD said unto me, Go, prophesy unto my people Israel."}, {"verse": 16, "start": 176.62, "end": 189.67, "ta": "இப்போதும் நீ கர்த்தருடைய வார்த்தையைக் கேள்; இஸ்ரவேலுக்கு விரோதமாய்த் தீர்க்கதரிசனம் சொல்லாதே, ஈசாக்கின் வம்சத்தாருக்கு விரோதமாக ஒன்றையும் சொல்லாதே என்று சொல்லுகிறாயே.", "en": "Now therefore hear thou the word of the LORD : Thou sayest, Prophesy not against Israel, and drop not thy word against the house of Isaac."}, {"verse": 17, "start": 189.67, "end": 213.77, "ta": "இதினிமித்தம்: உன் பெண்ஜாதி நகரத்தில் வேசியாவாள்; உன் குமாரரும் உன் குமாரத்திகளும் பட்டயத்தால் விழுவார்கள்; உன் வயல் அளவு நூலால் பங்கிட்டுக்கொள்ளப்படும்; நீயாவெனில் அசுத்தமான தேசத்திலே செத்துப்போவாய்; இஸ்ரவேலும் தன் தேசத்திலிருந்து சிறைபிடிக்கப்பட்டுக் கொண்டுபோகப்படுவான் என்று கர்த்தர் சொல்லுகிறார் என்றான்.", "en": "Therefore thus saith the LORD ; Thy wife shall be an harlot in the city, and thy sons and thy daughters shall fall by the sword, and thy land shall be divided by line; and thou shalt die in a polluted land: and Israel shall surely go into captivity forth of his land."}]}, "8": {"chapter": 8, "duration": 185.32, "audio_url": "audio_ot/OT30_08.mp3", "total_verses": 14, "verses": [{"verse": 1, "start": 3.8, "end": 11.52, "ta": "பின்பு கர்த்தராகிய ஆண்டவர் எனக்குக் காண்பித்ததாவது: இதோ, பழுத்த பழங்களுள்ள ஒரு கூடை இருந்தது.", "en": "Thus hath the Lord GOD shewed unto me: and behold a basket of summer fruit."}, {"verse": 2, "start": 11.52, "end": 29.74, "ta": "அவர்: ஆமோசே, நீ என்னத்தைக் காண்கிறாய் என்று கேட்டார்? பழுத்த பழங்களுள்ள ஒரு கூடையைக் காண்கிறேன் என்றேன். அப்பொழுது கர்த்தர் என்னை நோக்கி: என் ஜனமாகிய இஸ்ரவேலுக்கு முடிவுகாலம் வந்தது; இனி அவர்களை மன்னிக்கமாட்டேன்.", "en": "And he said, Amos, what seest thou? And I said, A basket of summer fruit. Then said the LORD unto me, The end is come upon my people of Israel; I will not again pass by them any more."}, {"verse": 3, "start": 29.74, "end": 42.08, "ta": "அந்நாளிலே தேவாலயப்பாட்டுகள் அலறுதலாக மாறும்; எல்லா இடத்திலும் திரளான பிரேதங்கள் புலம்பலில்லாமல் எறிந்துவிடப்படும் என்று கர்த்தராகிய ஆண்டவர் சொல்லுகிறார்.", "en": "And the songs of the temple shall be howlings in that day, saith the Lord GOD : there shall be many dead bodies in every place; they shall cast them forth with silence."}, {"verse": 4, "start": 42.08, "end": 47.0, "ta": "தேசத்தில் சிறுமைப்பட்டவர்களை ஒழியப்பண்ண, எளியவர்களை விழுங்கி,", "en": "Hear this, O ye that swallow up the needy, even to make the poor of the land to fail,"}, {"verse": 5, "start": 47.0, "end": 62.88, "ta": "நாங்கள் மரக்காலைக் குறைத்து, சேக்கல் நிறையை அதிகமாக்கி, கள்ளத்தராசினால் வஞ்சித்து, தரித்திரரைப் பணத்துக்கும், எளியவர்களை ஒருஜோடு பாதரட்சைக்கும் கொள்ளும்படிக்கும், தானியத்தின் பதரை விற்கும்படிக்கும்,", "en": "Saying, When will the new moon be gone, that we may sell corn? and the sabbath, that we may set forth wheat, making the ephah small, and the shekel great, and falsifying the balances by deceit?"}, {"verse": 6, "start": 62.88, "end": 75.66, "ta": "நாங்கள் தவசம் விற்கத்தக்கதாக மாதப்பிறப்பும், நாங்கள் தானியத்தின் பண்டசாலைகளைத் திறக்கத்தக்கதாக ஓய்வுநாளும் எப்போது முடியும் என்று சொல்லுகிறவர்களே இதைக் கேளுங்கள்.", "en": "That we may buy the poor for silver, and the needy for a pair of shoes; yea , and sell the refuse of the wheat?"}, {"verse": 7, "start": 75.66, "end": 84.26, "ta": "அவர்கள் செய்கைகளையெல்லாம் நான் ஒருபோதும் மறப்பதில்லையென்று கர்த்தர் யாக்கோபுடைய மகிமையின்பேரில் ஆணையிட்டார்.", "en": "The LORD hath sworn by the excellency of Jacob, Surely I will never forget any of their works."}, {"verse": 8, "start": 84.26, "end": 97.92, "ta": "இதினிமித்தம் தேசம் அதிரவும், அதின் குடிகள் எல்லாம் துக்கிக்கவும், எங்கும் நதிகளாய்ப் புரண்டோடவும், எகிப்தின் ஆற்றுவெள்ளத்தைப்போல் அடித்து, பெருவெள்ளமாகவும் வேண்டாமோ?", "en": "Shall not the land tremble for this, and every one mourn that dwelleth therein? and it shall rise up wholly as a flood; and it shall be cast out and drowned, as by the flood of Egypt."}, {"verse": 9, "start": 97.92, "end": 104.98, "ta": "அந்நாளிலே நான் மத்தியானத்திலே சூரியனை அஸ்தமிக்கப்பண்ணி பட்டப்பகலிலே தேசத்தை அந்தகாரப்படுத்தி,", "en": "And it shall come to pass in that day, saith the Lord GOD , that I will cause the sun to go down at noon, and I will darken the earth in the clear day:"}, {"verse": 10, "start": 104.98, "end": 129.59, "ta": "உங்கள் பண்டிகைகளைத் துக்கிப்பாகவும், உங்கள் பாட்டுகளையெல்லாம் புலம்பலாகவும் மாறப்பண்ணி, சகல அரைகளிலும் இரட்டையும், சகல தலைகளிலும் மொட்டையையும் வருவித்து அவர்களுடைய துக்கிப்பை ஒரே பிள்ளைக்காகத் துக்கிக்கிற துக்கிப்புக்குச் சமானமாக்கி, அவர்களுடைய முடிவைக் கசப்பான நாளாக்குவேன் என்று கர்த்தராகிய ஆண்டவர் சொல்லுகிறார்.", "en": "And I will turn your feasts into mourning, and all your songs into lamentation; and I will bring up sackcloth upon all loins, and baldness upon every head; and I will make it as the mourning of an only son , and the end thereof as a bitter day."}, {"verse": 11, "start": 129.59, "end": 147.82, "ta": "இதோ, நான் தேசத்தின்மேல் பஞ்சத்தை அனுப்பும் நாட்கள் வரும்; ஆகாரக் குறைவினால் உண்டாகிய பஞ்சமல்ல, ஜலக்குறைவினால் உண்டாகிய தாகமுமல்ல, கர்த்தருடைய வசனம் கேட்கக் கிடையாத பஞ்சத்தை அனுப்புவேன் என்று கர்த்தராகிய ஆண்டவர் சொல்லுகிறார்.", "en": "Behold, the days come, saith the Lord GOD , that I will send a famine in the land, not a famine of bread, nor a thirst for water, but of hearing the words of the LORD :"}, {"verse": 12, "start": 147.82, "end": 161.04, "ta": "அப்பொழுது அவர்கள் கர்த்தருடைய வசனத்தைத் தேட ஒரு சமுத்திரந்தொடங்கி மறு சமுத்திரமட்டும், வடதிசைதொடங்கிக் கீழ்த்திசைமட்டும் அலைந்து திரிந்தும் அதைக் கண்டடையாமற் போவார்கள்.", "en": "And they shall wander from sea to sea, and from the north even to the east, they shall run to and fro to seek the word of the LORD , and shall not find it ."}, {"verse": 13, "start": 161.04, "end": 167.43, "ta": "அந்நாளிலே செளந்தரியமுள்ள கன்னிகைகளும் வாலிபரும் தாகத்தினால் சோர்ந்துபோவார்கள்.", "en": "In that day shall the fair virgins and young men faint for thirst."}, {"verse": 14, "start": 167.43, "end": 183.82, "ta": "தாணே! உன் தேவனுடைய ஜீவனைக்கொண்டும், பெயெர்செபா மார்க்கத்தின் தேவனுடைய ஜீவனைக்கொண்டும் என்று சொல்லி, சமாரியாவின் தோஷத்தின்மேல் ஆணையிடுகிறவர்கள் விழுவார்கள்; இனி ஒருபோதும் எழுந்திருக்கமாட்டார்கள் என்றார்.", "en": "They that swear by the sin of Samaria, and say, Thy god, O Dan, liveth; and, The manner of Beer-sheba liveth; even they shall fall, and never rise up again."}]}, "9": {"chapter": 9, "duration": 235.63, "audio_url": "audio_ot/OT30_09.mp3", "total_verses": 15, "verses": [{"verse": 1, "start": 3.8, "end": 29.81, "ta": "ஆண்டவரைப் பலிபீடத்தின்மேல் நிற்கக்கண்டேன்; அவர்: நீ வாசல் நிலைகள் அசையும்படி போதிகையை அடித்து, அவைகளை அவர்கள் எல்லாருடைய தலையின்மேலும் விழ உடைத்துப்போடு; அவர்களுக்குப் பின்னாகவரும் மீதியானவர்களை நான் பட்டயத்தினால் கொன்றுபோடுவேன்; அவர்களில் ஓடுகிறவன் ஒருவனும் தப்புவதுமில்லை, அவர்களில் தப்புகிறவன் ஒருவனும் இரட்சிக்கப்படுவதுமில்லை.", "en": "I saw the Lord standing upon the altar: and he said, Smite the lintel of the door, that the posts may shake: and cut them in the head, all of them; and I will slay the last of them with the sword: he that fleeth of them shall not flee away, and he that escapeth of them shall not be delivered."}, {"verse": 2, "start": 29.81, "end": 44.42, "ta": "அவர்கள் பாதாளபரியந்தம் தோண்டிப் பதுங்கிக்கொண்டாலும், என் கை அவ்விடத்திலிருந்து அவர்களைப் பிடித்துக்கொண்டுவரும்; அவர்கள் வானபரியந்தம் ஏறினாலும் அவ்விடத்திலுமிருந்து அவர்களை இறங்கப்பண்ணுவேன்;", "en": "Though they dig into hell, thence shall mine hand take them; though they climb up to heaven, thence will I bring them down:"}, {"verse": 3, "start": 44.42, "end": 61.19, "ta": "அவர்கள் கர்மேலின் கொடுமுடியிலே ஒளித்துக்கொண்டாலும், அங்கே அவர்களைத் தேடிப்பிடிப்பேன்; அவர்கள் சமுத்திரத்தின் ஆழத்திலே போய் என் கண்களுக்கு மறைந்துகொண்டாலும், அங்கே அவர்களைக் கடிக்கப் பாம்புகளுக்குக் கட்டளையிடுவேன்.", "en": "And though they hide themselves in the top of Carmel, I will search and take them out thence; and though they be hid from my sight in the bottom of the sea, thence will I command the serpent, and he shall bite them:"}, {"verse": 4, "start": 61.19, "end": 75.37, "ta": "அவர்கள் தங்கள் சத்துருவுக்கு முன்பாகச் சிறைப்பட்டுப்போனாலும், அங்கே அவைகளைக் கொன்றுபோடப் பட்டயத்துக்கு நான் கட்டளையிட்டு, என் கண்களை அவர்கள்மேல் நன்மைக்கல்ல, தீமைக்கென்றே வைப்பேன்.", "en": "And though they go into captivity before their enemies, thence will I command the sword, and it shall slay them: and I will set mine eyes upon them for evil, and not for good."}, {"verse": 5, "start": 75.37, "end": 90.06, "ta": "சேனைகளின் கர்த்தராகிய ஆண்டவர் தேசத்தைத் தொட அது உருகிப்போம்; அப்பொழுது அதின் குடிகளெல்லாரும் புலம்புவார்கள்; எங்கும் நதியாய்ப் புரண்டோடி எகிப்தினுடைய ஆற்று வெள்ளத்தைப்போல் வெள்ளமாகும்.", "en": "And the Lord GOD of hosts is he that toucheth the land, and it shall melt, and all that dwell therein shall mourn: and it shall rise up wholly like a flood; and shall be drowned, as by the flood of Egypt."}, {"verse": 6, "start": 90.06, "end": 105.96, "ta": "அவர் வானத்தில் தமது மேலறைகளைக் கட்டி, பூமியில் தமது கீழறைகளை அஸ்திபாரப்படுத்தி, சமுத்திரத்தின் தண்ணீர்களை வரவழைத்து, அவர்களைப் பூமியினுடைய விசாலத்தின்மேல் ஊற்றுகிறவர்; கர்த்தர் என்பது அவருடைய நாமம்.", "en": "It is he that buildeth his stories in the heaven, and hath founded his troop in the earth; he that calleth for the waters of the sea, and poureth them out upon the face of the earth: The LORD is his name."}, {"verse": 7, "start": 105.96, "end": 124.3, "ta": "இஸ்ரவேல் புத்திரரே, நீங்கள் எனக்கு எத்தியோப்பியரின் புத்திரரைப்போல் இருக்கிறீர்கள் அல்லவோ என்று கர்த்தர் சொல்லுகிறார்; நான் இஸ்ரவேலை எகிப்துதேசத்திலிருந்தும், பெலிஸ்தரைக் கப்தோரிலிருந்தும், சீரியரைக் கீரிலிருந்தும் கொண்டுவரவில்லையோ?", "en": "Are ye not as children of the Ethiopians unto me, O children of Israel? saith the LORD . Have not I brought up Israel out of the land of Egypt? and the Philistines from Caphtor, and the Syrians from Kir?"}, {"verse": 8, "start": 124.3, "end": 141.21, "ta": "கர்த்தராகிய ஆண்டவரின் கண்கள் பாவமுள்ள ராஜ்யத்துக்கு விரோதமாக வைக்கப்பட்டிருக்கிறது; அதைப் பூமியின்மேல் இராதபடிக்கு அழித்துப்போடுவேன்; ஆகிலும் யாக்கோபின் வம்சத்தை முழுவதும் அழிக்கமாட்டேன் என்று கர்த்தர் சொல்லுகிறார்.", "en": "Behold, the eyes of the Lord GOD are upon the sinful kingdom, and I will destroy it from off the face of the earth; saving that I will not utterly destroy the house of Jacob, saith the LORD ."}, {"verse": 9, "start": 141.21, "end": 154.75, "ta": "இதோ, ஜல்லடையினால் சலித்தரிக்கிறதுபோல் இஸ்ரவேல் வம்சத்தாரை எல்லா ஜாதிகளுக்குள்ளும் சலித்தரிக்கும்படிக்கு நான் கட்டளையிடுவேன்; ஆனாலும் ஒரு கோதுமைமணியும் தரையிலே விழுவதில்லை.", "en": "For, lo, I will command, and I will sift the house of Israel among all nations, like as corn is sifted in a sieve, yet shall not the least grain fall upon the earth."}, {"verse": 10, "start": 154.75, "end": 164.64, "ta": "தீங்கு எங்களை அணுகுவதுமில்லை, எங்களுக்கு நேரிடுவதுமில்லையென்று என் ஜனத்தில் சொல்லுகிற பாவிகளெல்லாரும் பட்டயத்தினால் சாவார்கள்.", "en": "All the sinners of my people shall die by the sword, which say, The evil shall not overtake nor prevent us."}, {"verse": 11, "start": 164.64, "end": 171.08, "ta": "ஏதோமில் மீதியானவர்களையும் என் நாமம் விளங்கிய சகல ஜாதிகளையும் வசமாக்கிக்கொள்ளும்படிக்கு,", "en": "In that day will I raise up the tabernacle of David that is fallen, and close up the breaches thereof; and I will raise up his ruins, and I will build it as in the days of old:"}, {"verse": 12, "start": 171.08, "end": 187.63, "ta": "அந்நாளிலே விழுந்துபோன தாவீதின் கூடாரத்தை நான் திரும்ப எடுப்பித்து, அதின் திறப்புகளை அடைத்து, அதில் பழுதாய்ப்போனதைச் சீர்ப்படுத்தி, பூர்வநாட்களிலிருந்ததுபோல அதை ஸ்தாபிப்பேனென்று இதைச் செய்கிற கர்த்தர் சொல்லுகிறார்.", "en": "That they may possess the remnant of Edom, and of all the heathen, which are called by my name, saith the LORD that doeth this."}, {"verse": 13, "start": 187.63, "end": 203.4, "ta": "இதோ உழுகிறவன் அறுக்கிறவனையும், திராட்சப்பழங்களை ஆலையாடுகிறவன் விதைக்கிறவனையும் தொடர்ந்துபிடித்து, பர்வதங்கள் திராட்சரசமாய் வடிகிறதும், மேடுகளெல்லாம் கரைகிறதுமான நாட்கள்வரும் என்று கர்த்தர் சொல்லுகிறார்.", "en": "Behold, the days come, saith the LORD , that the plowman shall overtake the reaper, and the treader of grapes him that soweth seed; and the mountains shall drop sweet wine, and all the hills shall melt."}, {"verse": 14, "start": 203.4, "end": 221.31, "ta": "என் ஜனமாகிய இஸ்ரவேலின் சிறையிருப்பைத் திருப்புவேன்; அவர்கள் பாழான நகரங்களைக் கட்டி, அவைகளில் குடியிருந்து, திராட்சத்தோட்டங்களை நாட்டி, அவைகளுடைய பழரசத்தைக் குடித்து, தோட்டங்களை உண்டாக்கி, அவைகளின் கனிகளைப் புசிப்பார்கள்.", "en": "And I will bring again the captivity of my people of Israel, and they shall build the waste cities, and inhabit them; and they shall plant vineyards, and drink the wine thereof; they shall also make gardens, and eat the fruit of them."}, {"verse": 15, "start": 221.31, "end": 234.13, "ta": "அவர்களை அவர்கள் தேசத்திலே நாட்டுவேன்; நான் அவர்களுக்குக் கொடுத்த தேசத்திலிருந்து அவர்கள் இனிப் பிடுங்கப்படுவதில்லையென்று உன் தேவனாகிய கர்த்தர் சொல்லுகிறார் என்றார்.", "en": "And I will plant them upon their land, and they shall no more be pulled up out of their land which I have given them, saith the LORD thy God."}]}}};
}
